(1, 1, 93, 'multiple_choice', 'easy', 'Which of the following is NOT a traditional part of speech in English grammar?', '["Noun","Verb","Adjective","Paragraph"]'::jsonb, 'Paragraph', 1, 10, 'Identify and correctly use parts of speech', '["parts_of_speech","grammar_fundamentals"]'::jsonb, 'remember', '["grammar","mcq","intro"]'::jsonb, 0, TRUE, 25, NULL),
