(1, 1, 96, 'short_answer', 'easy', 'Name two examples of coordinating conjunctions.', '[]'::jsonb, 'and, but, or, nor, for, yet, so (any two)', 2, 15, 'Identify and correctly use parts of speech', '["conjunctions","coordinating"]'::jsonb, 'remember', '["grammar","parts_of_speech"]'::jsonb, 0, TRUE, 25, NULL),
