-- 3 Essay
(1, 1, 94, 'essay', 'hard', 'Explain the difference between transitive and intransitive verbs, providing three examples of each.', '[]'::jsonb, 'A comprehensive explanation of transitive vs intransitive verbs with appropriate examples.', 10, 45, 'Identify and correctly use parts of speech', '["verbs","transitive","intransitive"]'::jsonb, 'analyze', '["grammar","verbs","essay"]'::jsonb, 0, TRUE, 25, NULL),
(1, 1, 95, 'essay', 'medium', 'Discuss the importance of understanding basic English grammar for academic success in university studies.', '[]'::jsonb, 'Discussion should include clarity in writing, effective communication, and comprehension of academic texts.', 8, 40, 'Apply basic punctuation rules', '["grammar_importance","academic_writing"]'::jsonb, 'evaluate', '["grammar","academic","essay"]'::jsonb, 0, TRUE, 25, NULL),
(1, 1, 96, 'essay', 'hard', 'Analyze the following sentence structure: "Although tired from studying, the student, who had an exam the next day, stayed up late to review her notes." Identify all parts of speech and explain their functions.', '[]'::jsonb, 'Comprehensive analysis of all parts of speech and their functions in the given sentence.', 12, 50, 'Construct grammatically correct sentences', '["sentence_analysis","parts_of_speech"]'::jsonb, 'analyze', '["grammar","analysis","essay"]'::jsonb, 0, TRUE, 25, NULL),

-- 3 Practical
(1, 1, 93, 'practical', 'medium', 'Identify and label all parts of speech in the following paragraph: "The quick brown fox jumps over the lazy dog. This famous sentence contains every letter of the alphabet."', '[]'::jsonb, 'Noun: fox, dog, sentence, letter, alphabet; Adjective: quick, brown, lazy, famous; Verb: jumps, contains; Adverb: over; Article: The, the, a; Pronoun: This; Preposition: over; Conjunction: and (implied)', 5, 30, 'Identify and correctly use parts of speech', '["practical_analysis","parts_of_speech"]'::jsonb, 'apply', '["grammar","practical","analysis"]'::jsonb, 0, TRUE, 25, NULL),
(1, 1, 94, 'practical', 'hard', 'Correct the grammatical errors in the following sentences: 1. "Me and my friend is going to the library." 2. "She dont have no time for games." 3. "The books that was on the table is mine."', '[]'::jsonb, '1. "My friend and I are going to the library." 2. "She doesn''t have any time for games." OR "She has no time for games." 3. "The books that were on the table are mine."', 6, 35, 'Construct grammatically correct sentences', '["error_correction","grammar_rules"]'::jsonb, 'apply', '["grammar","practical","correction"]'::jsonb, 0, TRUE, 25, NULL),
(1, 1, 95, 'practical', 'medium', 'Convert the following simple sentences into compound or complex sentences using appropriate conjunctions: 1. "I studied hard. I passed the exam." 2. "She was tired. She continued working." 3. "The rain stopped. We went outside."', '[]'::jsonb, 'Sample answers: 1. "I studied hard, so I passed the exam." 2. "Although she was tired, she continued working." 3. "When the rain stopped, we went outside." (Other correct variations acceptable)', 5, 25, 'Construct grammatically correct sentences', '["sentence_construction","conjunctions"]'::jsonb, 'create', '["grammar","practical","construction"]'::jsonb, 0, TRUE, 25, NULL),

-- 3 Case Study
(1, 1, 96, 'case_study', 'hard', 'Case: A non-native English speaker writes: "Yesterday I go to market and buy many fruits. Apples, oranges, and banana. I very happy with my purchase." Analyze the grammatical errors and provide corrections with explanations of the grammar rules violated.', '[]'::jsonb, 'Errors: 1. Tense inconsistency ("go" should be "went") 2. Sentence fragment ("Apples, oranges, and banana.") 3. Missing verb ("I very happy") 4. Plural/singular inconsistency ("banana" should be "bananas") 5. Missing article ("market" could be "the market")', 15, 60, 'Construct grammatically correct sentences', '["error_analysis","grammar_rules"]'::jsonb, 'evaluate', '["grammar","case_study","ESL"]'::jsonb, 0, TRUE, 25, NULL),
(1, 1, 93, 'case_study', 'medium', 'Case: A business professional writes an email: "Please find attach the report what I prepared. It need your approval immediate." Identify the grammatical issues and rewrite the sentences correctly, explaining each correction.', '[]'::jsonb, 'Issues: 1. "attach" should be "attached" (past participle) 2. "what" should be "that" or "which" (relative pronoun) 3. "need" should be "needs" (subject-verb agreement) 4. "immediate" should be "immediately" (adverb form) Corrected: "Please find attached the report that I prepared. It needs your approval immediately."', 12, 45, 'Apply basic punctuation rules', '["business_grammar","error_correction"]'::jsonb, 'apply', '["grammar","case_study","business"]'::jsonb, 0, TRUE, 25, NULL),
(1, 1, 94, 'case_study', 'hard', 'Case: Analyze the following student''s paragraph for grammatical structure and coherence: "Learning grammar important. It help communicate good. Without grammar, people not understand you. My teacher say grammar is foundation of language." Provide a corrected version and explain the grammatical principles applied.', '[]'::jsonb, 'Analysis should cover: 1. Missing verbs ("is important", "helps", "do not", "says") 2. Adjective/adverb confusion ("good" should be "well") 3. Subject-verb agreement ("help" should be "helps") 4. Article usage ("the foundation") Corrected: "Learning grammar is important. It helps us communicate well. Without grammar, people would not understand you. My teacher says grammar is the foundation of language."', 15, 55, 'Construct grammatically correct sentences', '["paragraph_analysis","coherence"]'::jsonb, 'analyze', '["grammar","case_study","writing"]'::jsonb, 0, TRUE, 25, NULL);


