(2, 7, 62, 'short_answer', 'hard', 'Explain what an IP address is and why it''s important for networking.', '[]'::jsonb, 'IP address: unique identifier for devices on network; enables routing and communication between devices.', 3, 20, 'Explain how the internet works', '["IP_address","networking"]'::jsonb, 'analyze', '["networks","addressing"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Essay
(2, 7, 63, 'essay', 'hard', 'Discuss the evolution of computer networks from ARPANET to the modern internet. Include key technologies and protocols that enabled growth.', '[]'::jsonb, 'Evolution: ARPANET (1969), TCP/IP (1983), WWW (1991), broadband, mobile internet. Key: packet switching, DNS, HTTP, fiber optics.', 10, 45, 'Explain how the internet works', '["internet_evolution","history"]'::jsonb, 'analyze', '["internet","history"]'::jsonb, 0, TRUE, 21, NULL),
(2, 7, 64, 'essay', 'medium', 'Compare different network types (PAN, LAN, MAN, WAN) in terms of size, technology, and typical applications.', '[]'::jsonb, 'PAN: personal devices, Bluetooth. LAN: building, Ethernet/Wi-Fi. MAN: city, fiber. WAN: country/global, leased lines/satellite.', 9, 40, 'Describe network types and topologies', '["network_scales","comparison"]'::jsonb, 'analyze', '["networks","types"]'::jsonb, 0, TRUE, 21, NULL),
(2, 7, 65, 'essay', 'hard', 'Explain how data travels across the internet using protocols like TCP/IP, DNS, and HTTP. Include the role of routers and servers.', '[]'::jsonb, 'Process: DNS resolution, TCP handshake, packet routing via routers, HTTP request/response, data reassembly at destination.', 10, 45, 'Explain how the internet works', '["internet_protocols","data_flow"]'::jsonb, 'analyze', '["internet","protocols"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Practical
(2, 7, 61, 'practical', 'medium', 'Configure a basic home network: connect router, modem, and two devices. Document the setup and test connectivity.', '[]'::jsonb, 'Documentation: physical connections, wireless setup, device configuration, connectivity testing (ping, browsing).', 6, 30, 'Identify network devices', '["network_setup","practical"]'::jsonb, 'apply', '["networks","practical"]'::jsonb, 0, TRUE, 21, NULL),
(2, 7, 62, 'practical', 'hard', 'Use network diagnostic tools (ping, tracert/traceroute, ipconfig/ifconfig) to troubleshoot connectivity issues and document findings.', '[]'::jsonb, 'Diagnostic steps: check local connection, ping gateway, traceroute to external site, analyze results for bottlenecks.', 7, 35, 'Explain how the internet works', '["network_troubleshooting","diagnostics"]'::jsonb, 'apply', '["networks","troubleshooting"]'::jsonb, 0, TRUE, 21, NULL),
(2, 7, 63, 'practical', 'medium', 'Map a small office network topology including devices, connections, and IP addressing scheme.', '[]'::jsonb, 'Map: computers, printers, router, switch, server with IP assignments and connection lines showing topology.', 5, 25, 'Describe network types and topologies', '["network_mapping","topology"]'::jsonb, 'create', '["networks","mapping"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Case Study
(2, 7, 64, 'case_study', 'hard', 'Case: Design a network for a small business with 20 employees needing internet, file sharing, printing, and VoIP phones. Include hardware, topology, and security considerations.', '[]'::jsonb, 'Design: star topology, router/firewall, PoE switch for phones, file server, wireless access points, VLAN segmentation, security measures.', 15, 60, 'Describe network types and topologies', '["business_network","design"]'::jsonb, 'create', '["networks","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(2, 7, 65, 'case_study', 'medium', 'Case: A school needs to provide internet access while filtering inappropriate content. Propose a network architecture with content filtering and student/teacher access differences.', '[]'::jsonb, 'Architecture: firewall with content filtering, separate networks/VLANs for students and staff, authentication system, monitoring.', 12, 45, 'Identify network devices', '["school_network","content_filtering"]'::jsonb, 'create', '["networks","education"]'::jsonb, 0, TRUE, 21, NULL),
(2, 7, 61, 'case_study', 'hard', 'Case: Compare traditional on-premise network infrastructure with cloud-based networking. Analyze cost, scalability, management, and security implications for a growing company.', '[]'::jsonb, 'On-premise: control, upfront cost, maintenance. Cloud: scalability, OpEx model, vendor management, different security considerations.', 15, 55, 'Explain how the internet works', '["cloud_networking","comparison"]'::jsonb, 'evaluate', '["networks","cloud"]'::jsonb, 0, TRUE, 21, NULL);


INSERT INTO questions (course_id, study_unit_id, created_by, question_type, difficulty_level, question_text, options, correct_answer, marks, time_allocation, learning_outcome, keywords, bloom_taxonomy, tags, usage_count, is_active, approved_by, approved_at) VALUES
-- Study Unit 8: Data Representation and Number Systems (18 questions)
-- 3 Multiple Choice
(2, 8, 62, 'multiple_choice', 'easy', 'How many bits are in a byte?', '["4","8","16","32"]'::jsonb, '8', 1, 10, 'Understand bits and bytes', '["bits_bytes","conversion"]'::jsonb, 'remember', '["data","basics"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 63, 'multiple_choice', 'medium', 'Which number system uses base 16?', '["Binary","Decimal","Octal","Hexadecimal"]'::jsonb, 'Hexadecimal', 1, 10, 'Convert between number systems', '["number_systems","hexadecimal"]'::jsonb, 'remember', '["data","number_systems"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 64, 'multiple_choice', 'easy', 'What does ASCII stand for?', '["American Standard Code for Information Interchange","Advanced System Character Information Interface","Automated Symbol Code for Internet","American System Code for International Exchange"]'::jsonb, 'American Standard Code for Information Interchange', 1, 10, 'Explain data representation in computers', '["ASCII","definition"]'::jsonb, 'remember', '["data","encoding"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 True/False
(2, 8, 65, 'true_false', 'medium', 'Binary numbers use only 0s and 1s.', '["True","False"]'::jsonb, 'True', 1, 5, 'Convert between number systems', '["binary","basics"]'::jsonb, 'understand', '["data","binary"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 61, 'true_false', 'easy', '1 kilobyte equals 1000 bytes.', '["True","False"]'::jsonb, 'False', 1, 5, 'Understand bits and bytes', '["kilobyte","1024_bytes"]'::jsonb, 'remember', '["data","units"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 62, 'true_false', 'medium', 'Unicode can represent more characters than ASCII.', '["True","False"]'::jsonb, 'True', 1, 5, 'Explain data representation in computers', '["Unicode_vs_ASCII"]'::jsonb, 'understand', '["data","encoding"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Short Answer
(2, 8, 63, 'short_answer', 'easy', 'Convert decimal 10 to binary.', '[]'::jsonb, '1010', 2, 10, 'Convert between number systems', '["decimal_to_binary","conversion"]'::jsonb, 'apply', '["data","conversion"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 64, 'short_answer', 'medium', 'What is the binary equivalent of hexadecimal A?', '[]'::jsonb, '1010', 3, 15, 'Convert between number systems', '["hex_to_binary","conversion"]'::jsonb, 'apply', '["data","conversion"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 65, 'short_answer', 'hard', 'Explain how images are represented digitally using pixels and color values.', '[]'::jsonb, 'Images: grid of pixels, each pixel has color values (RGB), stored as binary numbers. Resolution affects quality and file size.', 3, 20, 'Explain data representation in computers', '["image_representation","pixels"]'::jsonb, 'analyze', '["data","images"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Essay
(2, 8, 61, 'essay', 'hard', 'Discuss the importance of number systems in computing. Why do computers use binary, while programmers often use hexadecimal and octal?', '[]'::jsonb, 'Binary: natural for electronics (on/off). Hexadecimal: compact representation of binary, easier for humans. Octal: historical use in systems.', 10, 45, 'Convert between number systems', '["number_systems_importance","computing"]'::jsonb, 'analyze', '["data","number_systems"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 62, 'essay', 'medium', 'Explain character encoding systems from ASCII to Unicode. How has the need to support global languages driven encoding evolution?', '[]'::jsonb, 'ASCII: 7-bit, English only. Extended ASCII: 8-bit, limited languages. Unicode: multi-byte, supports all languages, emoji.', 9, 40, 'Explain data representation in computers', '["encoding_evolution","Unicode"]'::jsonb, 'analyze', '["data","encoding"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 63, 'essay', 'hard', 'Compare different data representation methods for integers (signed, unsigned) and real numbers (fixed-point, floating-point). Include advantages and limitations.', '[]'::jsonb, 'Integers: signed (two''s complement), unsigned (positive only). Real numbers: fixed (precision limited), floating (range/precision trade-off).', 10, 45, 'Explain data representation in computers', '["number_representation","comparison"]'::jsonb, 'analyze', '["data","representation"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Practical
(2, 8, 64, 'practical', 'medium', 'Convert the following numbers: decimal 25 to binary, binary 1101 to decimal, hexadecimal 2F to decimal.', '[]'::jsonb, '25 = 11001, 1101 = 13, 2F = 47', 5, 30, 'Convert between number systems', '["conversion_practice"]'::jsonb, 'apply', '["data","conversion"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 65, 'practical', 'hard', 'Calculate the storage required for a 5-minute uncompressed audio recording at CD quality (44.1 kHz, 16-bit, stereo).', '[]'::jsonb, 'Calculation: 44,100 samples/sec × 16 bits/sample × 2 channels × 300 seconds ÷ 8 bits/byte ÷ 1,024^2 = ~50.5 MB', 6, 35, 'Understand bits and bytes', '["storage_calculation","audio"]'::jsonb, 'apply', '["data","calculation"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 61, 'practical', 'medium', 'Represent the word "CAT" in ASCII binary codes and hexadecimal.', '[]'::jsonb, 'C: 01000011 (43h), A: 01000001 (41h), T: 01010100 (54h)', 5, 25, 'Explain data representation in computers', '["ASCII_representation","practical"]'::jsonb, 'apply', '["data","ASCII"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Case Study
(2, 8, 62, 'case_study', 'hard', 'Case: A system needs to store patient records with text, numbers, dates, and images. Analyze data representation requirements and storage optimization strategies.', '[]'::jsonb, 'Analysis: text (Unicode), numbers (appropriate numeric types), dates (standard formats), images (compression formats). Storage: database design, indexing.', 15, 60, 'Explain data representation in computers', '["healthcare_data","storage_optimization"]'::jsonb, 'evaluate', '["data","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 63, 'case_study', 'medium', 'Case: Design a coding system for a library''s books using binary representation. Include how to encode book categories, authors, and unique identifiers.', '[]'::jsonb, 'Design: bits allocated for category, author code, unique ID. Example structure with field sizes and encoding explanation.', 12, 45, 'Convert between number systems', '["coding_system","design"]'::jsonb, 'create', '["data","design"]'::jsonb, 0, TRUE, 21, NULL),
(2, 8, 64, 'case_study', 'hard', 'Case: Compare data representation in early 8-bit computers vs. modern 64-bit systems. Analyze implications for memory addressing, number range, and computational precision.', '[]'::jsonb, '8-bit: 256 memory addresses, limited integers (-128 to 127). 64-bit: huge address space, large integers, high precision floating point.', 15, 55, 'Understand bits and bytes', '["architecture_evolution","bit_depth"]'::jsonb, 'evaluate', '["data","architecture"]'::jsonb, 0, TRUE, 21, NULL),

-- Study Unit 9: Computer Security and Ethics (18 questions)
-- 3 Multiple Choice
(2, 9, 65, 'multiple_choice', 'easy', 'What type of malware replicates itself to spread to other computers?', '["Trojan","Virus","Spyware","Adware"]'::jsonb, 'Virus', 1, 10, 'Identify security threats', '["malware","virus"]'::jsonb, 'remember', '["security","malware"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 61, 'multiple_choice', 'medium', 'Which authentication method uses something you have?', '["Password","Fingerprint","Security token","Retina scan"]'::jsonb, 'Security token', 1, 10, 'Apply basic security practices', '["authentication","factors"]'::jsonb, 'remember', '["security","authentication"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 62, 'multiple_choice', 'easy', 'What does phishing attempt to steal?', '["Hardware","Software","Personal information","Internet speed"]'::jsonb, 'Personal information', 1, 10, 'Identify security threats', '["phishing","definition"]'::jsonb, 'remember', '["security","attacks"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 True/False
(2, 9, 63, 'true_false', 'medium', 'Using the same password for all accounts is a good security practice.', '["True","False"]'::jsonb, 'False', 1, 5, 'Apply basic security practices', '["password_hygiene"]'::jsonb, 'understand', '["security","passwords"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 64, 'true_false', 'easy', 'Firewalls protect against viruses.', '["True","False"]'::jsonb, 'True', 1, 5, 'Apply basic security practices', '["firewall","protection"]'::jsonb, 'remember', '["security","firewall"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 65, 'true_false', 'medium', 'Ethical hackers have permission to test system security.', '["True","False"]'::jsonb, 'True', 1, 5, 'Explain ethical computing principles', '["ethical_hacking","authorization"]'::jsonb, 'understand', '["security","ethics"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Short Answer
(2, 9, 61, 'short_answer', 'easy', 'Name two types of malware.', '[]'::jsonb, 'Virus, Worm, Trojan, Spyware, Ransomware (any two)', 2, 10, 'Identify security threats', '["malware_types"]'::jsonb, 'remember', '["security","malware"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 62, 'short_answer', 'medium', 'What is two-factor authentication and why is it more secure?', '[]'::jsonb, '2FA requires two verification methods (e.g., password + SMS code). More secure because compromising one factor isn''t enough.', 3, 15, 'Apply basic security practices', '["2FA","authentication"]'::jsonb, 'understand', '["security","authentication"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 63, 'short_answer', 'hard', 'Explain the difference between encryption and hashing in data security.', '[]'::jsonb, 'Encryption: reversible with key, for confidentiality. Hashing: one-way, for integrity verification.', 3, 20, 'Apply basic security practices', '["encryption_vs_hashing"]'::jsonb, 'analyze', '["security","cryptography"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Essay
(2, 9, 64, 'essay', 'hard', 'Discuss the CIA triad in information security. How do confidentiality, integrity, and availability interrelate and sometimes conflict?', '[]'::jsonb, 'CIA: Confidentiality (access control), Integrity (data accuracy), Availability (accessibility). Conflicts: strong encryption may reduce availability; backups ensure availability but risk confidentiality.', 10, 45, 'Apply basic security practices', '["CIA_triad","security_principles"]'::jsonb, 'analyze', '["security","principles"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 65, 'essay', 'medium', 'Compare different types of cyber attacks (malware, phishing, DDoS, social engineering) and appropriate defense strategies for each.', '[]'::jsonb, 'Malware: antivirus. Phishing: user education. DDoS: network filtering. Social engineering: security training. Layered defense approach.', 9, 40, 'Identify security threats', '["cyber_attacks","defenses"]'::jsonb, 'analyze', '["security","attacks"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 61, 'essay', 'hard', 'Discuss ethical issues in computing including privacy, intellectual property, accessibility, and environmental impact. How can professionals balance innovation with responsibility?', '[]'::jsonb, 'Privacy: data collection limits. IP: software piracy. Accessibility: inclusive design. Environment: e-waste, energy use. Balance through ethical frameworks and regulations.', 10, 45, 'Explain ethical computing principles', '["computing_ethics","issues"]'::jsonb, 'evaluate', '["security","ethics"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Practical
(2, 9, 62, 'practical', 'medium', 'Create a strong password policy for an organization with requirements for length, complexity, and rotation.', '[]'::jsonb, 'Policy: minimum 12 characters, mix of uppercase/lowercase/numbers/symbols, change every 90 days, no reuse of last 5 passwords.', 6, 30, 'Apply basic security practices', '["password_policy","creation"]'::jsonb, 'create', '["security","practical"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 63, 'practical', 'hard', 'Perform a basic security audit on your own computer: check for updates, review installed programs, examine firewall settings, and document findings.', '[]'::jsonb, 'Audit: OS and software updates, unnecessary programs, firewall status, antivirus status. Document vulnerabilities and recommendations.', 7, 35, 'Identify security threats', '["security_audit","practical"]'::jsonb, 'apply', '["security","audit"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 64, 'practical', 'medium', 'Develop a social engineering awareness training outline for employees covering common tactics and response procedures.', '[]'::jsonb, 'Outline: phishing email identification, pretexting scenarios, tailgating prevention, reporting procedures, simulated exercises.', 5, 25, 'Apply basic security practices', '["security_training","awareness"]'::jsonb, 'create', '["security","training"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Case Study
(2, 9, 65, 'case_study', 'hard', 'Case: A hospital''s patient data system was breached. Analyze potential attack vectors, impacts on patients, and develop an incident response plan.', '[]'::jsonb, 'Analysis: vectors (phishing, unpatched software), impacts (privacy violations, trust loss). Response: containment, investigation, notification, remediation.', 15, 60, 'Identify security threats', '["healthcare_breach","incident_response"]'::jsonb, 'evaluate', '["security","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 61, 'case_study', 'medium', 'Case: A software company discovers employees are using unlicensed software. Develop an ethical software usage policy and implementation plan.', '[]'::jsonb, 'Policy: legal compliance requirements, approved software list, procurement process, employee training, audit procedures.', 12, 45, 'Explain ethical computing principles', '["software_ethics","compliance"]'::jsonb, 'create', '["security","compliance"]'::jsonb, 0, TRUE, 21, NULL),
(2, 9, 62, 'case_study', 'hard', 'Case: Compare security challenges and approaches for a traditional office network vs. a remote workforce using personal devices. Analyze risks and mitigation strategies.', '[]'::jsonb, 'Office: perimeter security, controlled devices. Remote: endpoint diversity, home network risks. Mitigation: VPN, endpoint protection, zero-trust architecture.', 15, 55, 'Apply basic security practices', '["remote_work_security","comparison"]'::jsonb, 'evaluate', '["security","remote"]'::jsonb, 0, TRUE, 21, NULL),

-- Study Unit 10: Troubleshooting and Maintenance (18 questions)
-- 3 Multiple Choice
(2, 10, 63, 'multiple_choice', 'easy', 'What is the first step in systematic troubleshooting?', '["Implement solution","Identify the problem","Test the solution","Document results"]'::jsonb, 'Identify the problem', 1, 10, 'Apply systematic troubleshooting', '["troubleshooting_steps","first_step"]'::jsonb, 'remember', '["troubleshooting","process"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 64, 'multiple_choice', 'medium', 'Which maintenance task helps prevent overheating?', '["Defragmenting","Cleaning dust","Updating software","Changing password"]'::jsonb, 'Cleaning dust', 1, 10, 'Perform basic maintenance tasks', '["preventive_maintenance","cleaning"]'::jsonb, 'remember', '["maintenance","cleaning"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 65, 'multiple_choice', 'easy', 'What does BSOD stand for in Windows troubleshooting?', '["Blue Screen of Death","Basic System Operation Delay","Boot System Override Detected","Binary System Operation Default"]'::jsonb, 'Blue Screen of Death', 1, 10, 'Diagnose common computer problems', '["BSOD","terminology"]'::jsonb, 'remember', '["troubleshooting","errors"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 True/False
(2, 10, 61, 'true_false', 'medium', 'Regular software updates can prevent many security issues.', '["True","False"]'::jsonb, 'True', 1, 5, 'Perform basic maintenance tasks', '["updates","security"]'::jsonb, 'understand', '["maintenance","updates"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 62, 'true_false', 'easy', 'Turning a computer off and on again can fix many problems.', '["True","False"]'::jsonb, 'True', 1, 5, 'Apply systematic troubleshooting', '["reboot","troubleshooting"]'::jsonb, 'remember', '["troubleshooting","basics"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 63, 'true_false', 'medium', 'All computer problems require professional repair.', '["True","False"]'::jsonb, 'False', 1, 5, 'Diagnose common computer problems', '["self_troubleshooting","capability"]'::jsonb, 'understand', '["troubleshooting","self-help"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Short Answer
(2, 10, 64, 'short_answer', 'easy', 'Name two common symptoms of computer problems.', '[]'::jsonb, 'Slow performance, Crashes/freezes, No power, Strange noises, Error messages (any two)', 2, 10, 'Diagnose common computer problems', '["symptoms","common"]'::jsonb, 'remember', '["troubleshooting","symptoms"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 65, 'short_answer', 'medium', 'What is the purpose of a backup in computer maintenance?', '[]'::jsonb, 'To protect data from loss due to hardware failure, malware, accidental deletion, or disasters.', 3, 15, 'Perform basic maintenance tasks', '["backup","purpose"]'::jsonb, 'understand', '["maintenance","backup"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 61, 'short_answer', 'hard', 'Explain the divide-and-conquer approach to troubleshooting complex computer problems.', '[]'::jsonb, 'Methodically isolate the problem by testing components/subsystems to narrow down the cause, eliminating variables systematically.', 3, 20, 'Apply systematic troubleshooting', '["troubleshooting_methodology","divide_conquer"]'::jsonb, 'analyze', '["troubleshooting","methodology"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Essay
(2, 10, 62, 'essay', 'hard', 'Discuss a comprehensive preventive maintenance schedule for computer systems, covering daily, weekly, monthly, and annual tasks.', '[]'::jsonb, 'Daily: backup verification, virus scans. Weekly: software updates, disk cleanup. Monthly: defragmentation, hardware cleaning. Annual: deep cleaning, component inspection.', 10, 45, 'Perform basic maintenance tasks', '["maintenance_schedule","preventive"]'::jsonb, 'analyze', '["maintenance","schedule"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 63, 'essay', 'medium', 'Compare software vs. hardware troubleshooting approaches. How do diagnostic techniques differ for each category?', '[]'::jsonb, 'Software: logs, safe mode, reinstallation. Hardware: visual inspection, component swapping, diagnostic tools. Different tools and escalation paths.', 9, 40, 'Diagnose common computer problems', '["software_vs_hardware_troubleshooting"]'::jsonb, 'analyze', '["troubleshooting","comparison"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 64, 'essay', 'hard', 'Explain the importance of documentation in troubleshooting processes. How does proper documentation improve efficiency and knowledge transfer?', '[]'::jsonb, 'Documentation: records symptoms, attempted solutions, results. Benefits: avoids repetition, builds knowledge base, enables collaboration, supports training.', 10, 45, 'Apply systematic troubleshooting', '["documentation","importance"]'::jsonb, 'analyze', '["troubleshooting","documentation"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Practical
(2, 10, 65, 'practical', 'medium', 'Troubleshoot a simulated "no display" problem using systematic approach. Document each step and potential causes tested.', '[]'::jsonb, 'Steps: check power, monitor connections, try different cable, test with another monitor, check graphics card, BIOS settings.', 6, 30, 'Apply systematic troubleshooting', '["no_display_troubleshooting"]'::jsonb, 'apply', '["troubleshooting","practical"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 61, 'practical', 'hard', 'Create a troubleshooting flowchart for common internet connectivity issues covering modem, router, computer, and ISP levels.', '[]'::jsonb, 'Flowchart: start with "no internet", check device connectivity, router lights, modem status, ISP outage, DNS issues, firewall settings.', 7, 35, 'Diagnose common computer problems', '["troubleshooting_flowchart","connectivity"]'::jsonb, 'create', '["troubleshooting","flowchart"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 62, 'practical', 'medium', 'Perform disk cleanup and defragmentation on a Windows system (or equivalent on other OS). Document before/after performance metrics.', '[]'::jsonb, 'Documentation: initial disk usage, fragmentation percentage. Process steps. Results: freed space, improved fragmentation status.', 5, 25, 'Perform basic maintenance tasks', '["disk_maintenance","practical"]'::jsonb, 'apply', '["maintenance","practical"]'::jsonb, 0, TRUE, 21, NULL),

-- 3 Case Study
(2, 10, 63, 'case_study', 'hard', 'Case: A company''s computers are experiencing widespread slowdowns. Conduct a root cause analysis considering hardware, software, network, and user factors.', '[]'::jsonb, 'Analysis: check for malware, network congestion, outdated hardware, bloated software, user behavior. Systematic elimination to find primary cause.', 15, 60, 'Diagnose common computer problems', '["performance_troubleshooting","root_cause"]'::jsonb, 'evaluate', '["troubleshooting","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 64, 'case_study', 'medium', 'Case: Design a maintenance program for a computer lab with 50 machines. Include schedules, responsibilities, tools needed, and documentation requirements.', '[]'::jsonb, 'Program: daily checklist (cleanliness, basic functionality), weekly updates, monthly deep clean, semester hardware audit. Staff assignments, maintenance logs.', 12, 45, 'Perform basic maintenance tasks', '["lab_maintenance","program_design"]'::jsonb, 'create', '["maintenance","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(2, 10, 65, 'case_study', 'hard', 'Case: Compare troubleshooting approaches for individual desktop support vs. enterprise IT support. Analyze differences in scale, tools, documentation, and escalation procedures.', '[]'::jsonb, 'Individual: hands-on, varied problems. Enterprise: ticketing systems, remote tools, standardized procedures, specialized teams, SLAs, knowledge bases.', 15, 55, 'Apply systematic troubleshooting', '["support_scales","comparison"]'::jsonb, 'evaluate', '["troubleshooting","enterprise"]'::jsonb, 0, TRUE, 21, NULL);


