(3, 30, 69, 'multiple_choice', 'medium', 'Which project management phase comes after planning?', '["Initiating","Executing","Monitoring","Closing"]'::jsonb, 'Executing', 1, 10, 'Explain project management phases', '["project_phases","executing"]'::jsonb, 'remember', '["project","phases"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 70, 'multiple_choice', 'easy', 'What is a Gantt chart used for?', '["Budget tracking","Schedule visualization","Risk assessment","Team communication"]'::jsonb, 'Schedule visualization', 1, 10, 'Identify project management tools', '["Gantt_chart","purpose"]'::jsonb, 'remember', '["project","tools"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 66, 'true_false', 'medium', 'Agile methodology emphasizes rigid long-term planning.', '["True","False"]'::jsonb, 'False', 1, 5, 'Describe project methodologies', '["agile_flexibility"]'::jsonb, 'understand', '["project","agile"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 67, 'true_false', 'easy', 'Scope creep can cause project delays and budget overruns.', '["True","False"]'::jsonb, 'True', 1, 5, 'Explain project management phases', '["scope_creep","impact"]'::jsonb, 'remember', '["project","scope"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 68, 'true_false', 'medium', 'All IT projects follow the same methodology.', '["True","False"]'::jsonb, 'False', 1, 5, 'Describe project methodologies', '["methodology_selection","context"]'::jsonb, 'understand', '["project","methodologies"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 69, 'short_answer', 'easy', 'Name three project management methodologies.', '[]'::jsonb, 'Waterfall, Agile, Scrum, Kanban, PRINCE2 (any three)', 2, 10, 'Describe project methodologies', '["PM_methodologies","list"]'::jsonb, 'remember', '["project","methodologies"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 70, 'short_answer', 'medium', 'What are the triple constraints of project management?', '[]'::jsonb, 'Scope, Time, Cost', 3, 15, 'Explain project management phases', '["triple_constraints","PM"]'::jsonb, 'remember', '["project","constraints"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 66, 'short_answer', 'hard', 'Explain the difference between waterfall and agile project management approaches.', '[]'::jsonb, 'Waterfall: linear, sequential phases, fixed requirements. Agile: iterative, incremental, flexible requirements, frequent deliverables.', 3, 20, 'Describe project methodologies', '["waterfall_vs_agile"]'::jsonb, 'analyze', '["project","methodologies"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 67, 'essay', 'hard', 'Discuss the role of stakeholders in IT project management. How should project managers identify, engage, and manage different stakeholder groups?', '[]'::jsonb, 'Stakeholders: sponsors, users, team, regulators. Identification: stakeholder analysis. Engagement: communication plans, regular updates. Management: expectation setting, conflict resolution.', 10, 45, 'Explain project management phases', '["stakeholder_management","PM"]'::jsonb, 'analyze', '["project","stakeholders"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 68, 'essay', 'medium', 'Compare risk management in traditional vs agile IT projects. How are risks identified, assessed, and mitigated in each approach?', '[]'::jsonb, 'Traditional: upfront risk register, planned mitigation. Agile: continuous risk assessment, adaptive responses, shorter feedback cycles. Different tools and timing.', 9, 40, 'Explain project management phases', '["risk_management","comparison"]'::jsonb, 'analyze', '["project","risk"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 69, 'essay', 'hard', 'Analyze how DevOps integrates development and operations, changing traditional IT project management and software delivery lifecycle.', '[]'::jsonb, 'DevOps: continuous integration/delivery, automation, collaboration. Changes: faster releases, reduced silos, shared responsibility, monitoring integration.', 10, 45, 'Describe project methodologies', '["DevOps","impact_PM"]'::jsonb, 'evaluate', '["project","DevOps"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 70, 'practical', 'medium', 'Create a project charter for developing a mobile app, including objectives, scope, stakeholders, and high-level timeline.', '[]'::jsonb, 'Charter: project title, purpose, objectives, scope (in/out), stakeholders, risks, assumptions, constraints, milestones, approval.', 6, 30, 'Explain project management phases', '["project_charter_creation"]'::jsonb, 'create', '["project","practical"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 66, 'practical', 'hard', 'Develop a work breakdown structure (WBS) for a website development project with at least three levels of decomposition.', '[]'::jsonb, 'WBS: Project → Phases (planning, design, development, testing, deployment) → Tasks (requirements, wireframes, coding, etc.) → Subtasks.', 7, 35, 'Identify project management tools', '["WBS_creation","decomposition"]'::jsonb, 'create', '["project","WBS"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 67, 'practical', 'medium', 'Use project management software (like Trello, Asana, or MS Project) to create a simple project plan with tasks, assignments, and deadlines.', '[]'::jsonb, 'Plan: project setup, task creation, assignment to team members, due dates, dependencies, progress tracking. Screenshots/documentation.', 5, 25, 'Identify project management tools', '["PM_software_practical"]'::jsonb, 'apply', '["project","tools"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 68, 'case_study', 'hard', 'Case: An ERP implementation project is behind schedule and over budget. Analyze root causes and propose recovery strategies including methodology adjustment.', '[]'::jsonb, 'Analysis: scope creep, poor requirements, resistance to change. Recovery: reassess scope, increase resources, change management, consider agile elements.', 15, 60, 'Explain project management phases', '["project_recovery","ERP_implementation"]'::jsonb, 'evaluate', '["project","case_study"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 69, 'case_study', 'medium', 'Case: Compare using traditional waterfall vs agile for a software product development. Analyze which approach suits different project characteristics.', '[]'::jsonb, 'Waterfall: clear requirements, fixed scope, regulatory projects. Agile: uncertain requirements, need for flexibility, customer collaboration, innovative products.', 12, 45, 'Describe project methodologies', '["methodology_selection","analysis"]'::jsonb, 'evaluate', '["project","methodology"]'::jsonb, 0, TRUE, 22, NULL),
(3, 30, 70, 'case_study', 'hard', 'Case: Analyze how IT project management differs for internal IT projects vs consulting/client projects. Discuss stakeholder dynamics, success criteria, and risk profiles.', '[]'::jsonb, 'Internal: familiar stakeholders, organizational politics, long-term ownership. Consulting: client relationships, contractual obligations, defined deliverables, payment milestones.', 15, 55, 'Explain project management phases', '["internal_vs_consulting_PM"]'::jsonb, 'evaluate', '["project","context"]'::jsonb, 0, TRUE, 22, NULL);


