-- Course 4, Study Units 1-10 (ids 31-40)
-- Study Unit 1 (id=31): Introduction to Office Productivity Software
(4, 31, 61, 'multiple_choice', 'easy', 'Which of these is NOT typically part of an office productivity suite?', '["Word Processor","Spreadsheet","Presentation Software","Photo Editing Software"]'::jsonb, 'Photo Editing Software', 1, 10, 'Identify office productivity software', '["office_suite_components"]'::jsonb, 'remember', '["office","basics"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 62, 'multiple_choice', 'medium', 'What is the primary purpose of office productivity software?', '["Playing games","Creating business documents","Programming","System administration"]'::jsonb, 'Creating business documents', 1, 10, 'Explain software integration', '["office_software_purpose"]'::jsonb, 'remember', '["office","purpose"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 63, 'multiple_choice', 'easy', 'Which software would you use to create a letter or report?', '["Spreadsheet","Word Processor","Presentation Software","Database"]'::jsonb, 'Word Processor', 1, 10, 'Identify office productivity software', '["word_processor_use"]'::jsonb, 'remember', '["office","applications"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 64, 'true_false', 'medium', 'Microsoft Office and LibreOffice are examples of office productivity suites.', '["True","False"]'::jsonb, 'True', 1, 5, 'Identify office productivity software', '["office_suite_examples"]'::jsonb, 'understand', '["office","suites"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 65, 'true_false', 'easy', 'Office software can only be installed on Windows computers.', '["True","False"]'::jsonb, 'False', 1, 5, 'Navigate software interfaces', '["office_platforms"]'::jsonb, 'remember', '["office","platforms"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 61, 'true_false', 'medium', 'The ribbon interface is common to most modern office applications.', '["True","False"]'::jsonb, 'True', 1, 5, 'Navigate software interfaces', '["ribbon_interface"]'::jsonb, 'understand', '["office","interface"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 62, 'short_answer', 'easy', 'Name three common office productivity applications.', '[]'::jsonb, 'Word Processor, Spreadsheet, Presentation Software, Database, Email Client (any three)', 2, 10, 'Identify office productivity software', '["office_apps_list"]'::jsonb, 'remember', '["office","applications"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 63, 'short_answer', 'medium', 'What is the advantage of using an integrated office suite over separate applications?', '[]'::jsonb, 'Consistent interface, easy data sharing between apps, unified file format, cost savings', 3, 15, 'Explain software integration', '["office_suite_advantages"]'::jsonb, 'understand', '["office","integration"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 64, 'short_answer', 'hard', 'Explain how cloud-based office software differs from traditional installed software.', '[]'::jsonb, 'Cloud-based: accessed via browser, automatic updates, collaboration features, subscription model. Traditional: installed locally, one-time purchase, limited collaboration.', 3, 20, 'Navigate software interfaces', '["cloud_vs_traditional_office"]'::jsonb, 'analyze', '["office","cloud"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 65, 'essay', 'hard', 'Discuss the evolution of office productivity software from standalone applications to integrated suites and cloud-based collaboration platforms.', '[]'::jsonb, 'Evolution: standalone apps (WordStar, Lotus) → integrated suites (Office 95) → ribbon interface (Office 2007) → cloud collaboration (Office 365, Google Workspace). Impact on workflow and collaboration.', 10, 45, 'Explain software integration', '["office_software_evolution"]'::jsonb, 'analyze', '["office","evolution"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 61, 'essay', 'medium', 'Compare Microsoft Office, Google Workspace, and LibreOffice in terms of cost, features, collaboration, and platform compatibility.', '[]'::jsonb, 'MS Office: comprehensive, expensive, desktop-focused. Google Workspace: cloud-native, real-time collaboration, subscription. LibreOffice: free, open-source, desktop, compatibility challenges.', 9, 40, 'Identify office productivity software', '["office_suite_comparison"]'::jsonb, 'analyze', '["office","comparison"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 62, 'essay', 'hard', 'Analyze how office productivity software has transformed business workflows, focusing on document creation, collaboration, and information management.', '[]'::jsonb, 'Transformation: from typewriters to word processors, paper ledgers to spreadsheets, slide projectors to presentations. Collaboration: email attachments → cloud sharing → real-time co-editing.', 10, 45, 'Explain software integration', '["office_software_impact"]'::jsonb, 'evaluate', '["office","impact"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 63, 'practical', 'medium', 'Create a folder structure on your computer for organizing different types of office documents: letters, reports, budgets, presentations.', '[]'::jsonb, 'Structure: Documents → Business → Letters, Reports, Budgets, Presentations. Clear naming conventions and subfolders.', 5, 30, 'Navigate software interfaces', '["folder_organization","practical"]'::jsonb, 'apply', '["office","organization"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 64, 'practical', 'hard', 'Install and configure an office suite (LibreOffice or equivalent). Document the installation process and explore the interface of each main application.', '[]'::jsonb, 'Documentation: download source, installation steps, first launch, interface exploration of Writer, Calc, Impress. Screenshots and descriptions.', 6, 35, 'Navigate software interfaces', '["office_installation","exploration"]'::jsonb, 'apply', '["office","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 65, 'practical', 'medium', 'Map business tasks to appropriate office applications: sales report (data analysis), company newsletter (document), quarterly presentation, customer database.', '[]'::jsonb, 'Sales report: spreadsheet. Newsletter: word processor. Presentation: presentation software. Customer database: database application.', 4, 25, 'Identify office productivity software', '["task_application_mapping"]'::jsonb, 'apply', '["office","mapping"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 61, 'case_study', 'hard', 'Case: A small non-profit organization needs to choose office software with limited budget. Compare free/open-source vs subscription cloud vs traditional purchase options.', '[]'::jsonb, 'Analysis: LibreOffice (free, one-time), Google Workspace (subscription, collaboration), MS Office (purchase, industry standard). Recommendation based on needs, budget, tech skills.', 15, 60, 'Identify office productivity software', '["software_selection","nonprofit"]'::jsonb, 'evaluate', '["office","selection"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 62, 'case_study', 'medium', 'Case: A department uses different office software versions causing compatibility issues. Develop a standardization plan including software choice, training, and migration.', '[]'::jsonb, 'Plan: needs assessment, software selection, version standardization, file format conversion, user training, support plan, timeline.', 12, 45, 'Navigate software interfaces', '["standardization_plan","compatibility"]'::jsonb, 'create', '["office","standardization"]'::jsonb, 0, TRUE, 21, NULL),
(4, 31, 63, 'case_study', 'hard', 'Case: Analyze how the shift to remote work has changed office software usage patterns, emphasizing cloud collaboration, mobile access, and security considerations.', '[]'::jsonb, 'Changes: increased cloud adoption, real-time collaboration needs, mobile editing, video conferencing integration. Security: data protection, access controls, compliance.', 15, 55, 'Explain software integration', '["remote_work_impact","office_software"]'::jsonb, 'evaluate', '["office","remote"]'::jsonb, 0, TRUE, 21, NULL);


INSERT INTO questions (course_id, study_unit_id, created_by, question_type, difficulty_level, question_text, options, correct_answer, marks, time_allocation, learning_outcome, keywords, bloom_taxonomy, tags, usage_count, is_active, approved_by, approved_at) VALUES
-- Study Unit 2 (id=32): Word Processing Fundamentals
(4, 32, 64, 'multiple_choice', 'easy', 'Which key combination is commonly used to save a document?', '["Ctrl+C","Ctrl+V","Ctrl+S","Ctrl+X"]'::jsonb, 'Ctrl+S', 1, 10, 'Navigate software interfaces', '["keyboard_shortcuts","save"]'::jsonb, 'remember', '["word","basics"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 65, 'multiple_choice', 'medium', 'What does the term "font" refer to in word processing?', '["Document size","Text style and appearance","Page orientation","Document margins"]'::jsonb, 'Text style and appearance', 1, 10, 'Apply styles and formatting', '["font_definition"]'::jsonb, 'remember', '["word","formatting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 61, 'multiple_choice', 'easy', 'Which alignment places text evenly between left and right margins?', '["Left align","Right align","Center align","Justify"]'::jsonb, 'Justify', 1, 10, 'Apply styles and formatting', '["text_alignment","justify"]'::jsonb, 'remember', '["word","formatting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 62, 'true_false', 'medium', 'Headers and footers appear on every page of a document.', '["True","False"]'::jsonb, 'True', 1, 5, 'Create and format documents', '["headers_footers","definition"]'::jsonb, 'understand', '["word","layout"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 63, 'true_false', 'easy', 'The spell checker can identify all grammatical errors.', '["True","False"]'::jsonb, 'False', 1, 5, 'Use editing and proofing tools', '["spell_check_limitations"]'::jsonb, 'remember', '["word","editing"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 64, 'true_false', 'medium', 'Line spacing of 1.5 means one and a half times the normal spacing.', '["True","False"]'::jsonb, 'True', 1, 5, 'Apply styles and formatting', '["line_spacing","definition"]'::jsonb, 'understand', '["word","formatting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 65, 'short_answer', 'easy', 'Name three types of document formatting you can apply in word processing.', '[]'::jsonb, 'Font style, Size, Color, Alignment, Line spacing, Margins, Indentation (any three)', 2, 10, 'Apply styles and formatting', '["formatting_types"]'::jsonb, 'remember', '["word","formatting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 61, 'short_answer', 'medium', 'What is the difference between Save and Save As?', '[]'::jsonb, 'Save: updates existing file. Save As: creates new file with different name/location, keeps original unchanged.', 3, 15, 'Navigate software interfaces', '["save_vs_save_as"]'::jsonb, 'understand', '["word","basics"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 62, 'short_answer', 'hard', 'Explain how styles improve document consistency and efficiency compared to manual formatting.', '[]'::jsonb, 'Styles: predefined formatting sets; ensure consistency across document; faster updates; enable automatic table of contents; maintain document structure.', 3, 20, 'Apply styles and formatting', '["styles_benefits","consistency"]'::jsonb, 'analyze', '["word","styles"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 63, 'essay', 'hard', 'Discuss professional document formatting principles for business correspondence, academic papers, and reports. Include margins, fonts, spacing, and structure.', '[]'::jsonb, 'Business letters: letterhead, block format. Academic papers: title page, headings, citations, references. Reports: executive summary, sections, appendices. Each has specific formatting standards.', 10, 45, 'Create and format documents', '["document_formatting_principles"]'::jsonb, 'analyze', '["word","professional"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 64, 'essay', 'medium', 'Compare the advantages of using templates versus creating documents from scratch for different business scenarios.', '[]'::jsonb, 'Templates: consistency, time-saving, branding control, reduced errors. From scratch: complete flexibility, unique requirements, one-time documents. Scenario-based recommendations.', 9, 40, 'Apply styles and formatting', '["templates_vs_scratch","advantages"]'::jsonb, 'analyze', '["word","templates"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 65, 'essay', 'hard', 'Analyze how word processing features like track changes, comments, and version history support collaborative document creation and review processes.', '[]'::jsonb, 'Track changes: shows edits. Comments: feedback without changing text. Version history: tracks revisions, allows rollback. Enables distributed collaboration and review cycles.', 10, 45, 'Use editing and proofing tools', '["collaboration_features","word_processing"]'::jsonb, 'evaluate', '["word","collaboration"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 61, 'practical', 'medium', 'Create a properly formatted business letter with letterhead, date, recipient address, salutation, body, closing, and signature block.', '[]'::jsonb, 'Document includes all elements with proper formatting: margins, alignment, spacing, professional font. Content: placeholder text with correct structure.', 6, 30, 'Create and format documents', '["business_letter_creation"]'::jsonb, 'create', '["word","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 62, 'practical', 'hard', 'Format a 3-page academic paper with title page, headings, citations, bibliography, and proper page numbering using styles and sections.', '[]'::jsonb, 'Paper includes: title page (no number), main content (page numbers), headings hierarchy, citation style (APA/MLA), bibliography section. Styles used consistently.', 7, 35, 'Apply styles and formatting', '["academic_paper_formatting"]'::jsonb, 'apply', '["word","academic"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 63, 'practical', 'medium', 'Use proofing tools to check spelling, grammar, and readability of a provided document. Document errors found and corrections made.', '[]'::jsonb, 'Process: run spell check, grammar check, readability statistics. Documentation: list of errors, corrections, suggestions for improvement.', 5, 25, 'Use editing and proofing tools', '["proofing_practical"]'::jsonb, 'apply', '["word","proofing"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 64, 'case_study', 'hard', 'Case: A company''s documents have inconsistent formatting. Develop a style guide and template system to standardize reports, memos, and letters.', '[]'::jsonb, 'Style guide: fonts, colors, margins, heading styles. Templates: report template, memo template, letter template. Implementation plan and training.', 15, 60, 'Apply styles and formatting', '["style_guide_development","standardization"]'::jsonb, 'create', '["word","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 65, 'case_study', 'medium', 'Case: Compare document collaboration using shared network drives vs cloud-based word processing. Analyze version control, access management, and real-time editing.', '[]'::jsonb, 'Network drives: file locking, version confusion, access issues. Cloud: real-time co-editing, version history, comment threads, access controls. Advantages of cloud for collaboration.', 12, 45, 'Use editing and proofing tools', '["collaboration_methods_comparison"]'::jsonb, 'evaluate', '["word","collaboration"]'::jsonb, 0, TRUE, 21, NULL),
(4, 32, 61, 'case_study', 'hard', 'Case: Analyze accessibility features in word processors (headings, alt text, reading order) and their importance for creating inclusive documents for users with disabilities.', '[]'::jsonb, 'Features: heading styles for screen readers, alt text for images, proper reading order, sufficient color contrast. Importance: legal compliance, inclusivity, broader audience reach.', 15, 55, 'Create and format documents', '["accessibility_features","inclusive_design"]'::jsonb, 'evaluate', '["word","accessibility"]'::jsonb, 0, TRUE, 21, NULL);


