-- Study Unit 3 (id=33): Advanced Word Processing
(4, 33, 62, 'multiple_choice', 'easy', 'What is mail merge used for?', '["Creating form letters","Drawing graphics","Checking spelling","Formatting tables"]'::jsonb, 'Creating form letters', 1, 10, 'Create mail merge documents', '["mail_merge_purpose"]'::jsonb, 'remember', '["word","mail_merge"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 63, 'multiple_choice', 'medium', 'Which feature automatically creates a list of headings with page numbers?', '["Header","Footer","Table of Contents","Index"]'::jsonb, 'Table of Contents', 1, 10, 'Manage long documents with TOC and references', '["table_of_contents","feature"]'::jsonb, 'remember', '["word","toc"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 65, 'true_false', 'medium', 'Mail merge requires both a main document and a data source.', '["True","False"]'::jsonb, 'True', 1, 5, 'Create mail merge documents', '["mail_merge_components"]'::jsonb, 'understand', '["word","mail_merge"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 61, 'true_false', 'easy', 'Templates can include both content and formatting.', '["True","False"]'::jsonb, 'True', 1, 5, 'Design tables and templates', '["templates_content_formatting"]'::jsonb, 'remember', '["word","templates"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 62, 'true_false', 'medium', 'Footnotes and endnotes serve the same purpose and can be used interchangeably.', '["True","False"]'::jsonb, 'False', 1, 5, 'Manage long documents with TOC and references', '["footnotes_vs_endnotes"]'::jsonb, 'understand', '["word","references"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 63, 'short_answer', 'easy', 'Name three elements that can be included in a document template.', '[]'::jsonb, 'Headers/footers, Styles, Placeholder text, Logos, Page numbers, Watermarks (any three)', 2, 10, 'Design tables and templates', '["template_elements"]'::jsonb, 'remember', '["word","templates"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 64, 'short_answer', 'medium', 'What is the purpose of using sections in a long document?', '[]'::jsonb, 'Sections allow different formatting (margins, headers, page orientation) within the same document.', 3, 15, 'Manage long documents with TOC and references', '["sections_purpose"]'::jsonb, 'understand', '["word","sections"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 65, 'short_answer', 'hard', 'Explain the mail merge process from data source preparation to merged document output.', '[]'::jsonb, 'Process: 1) Prepare data source (spreadsheet/database), 2) Create main document with merge fields, 3) Connect data source, 4) Insert merge fields, 5) Preview and complete merge, 6) Save/print output.', 3, 20, 'Create mail merge documents', '["mail_merge_process","steps"]'::jsonb, 'analyze', '["word","mail_merge"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 61, 'essay', 'hard', 'Discuss advanced document management techniques for long documents: sections, headers/footers, table of contents, indexes, and cross-references.', '[]'::jsonb, 'Sections: control layout changes. Headers/footers: consistent branding. TOC: navigation. Index: keyword access. Cross-references: link to figures/tables. Essential for technical manuals, theses, reports.', 10, 45, 'Manage long documents with TOC and references', '["long_document_management"]'::jsonb, 'analyze', '["word","advanced"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 62, 'essay', 'medium', 'Compare the use of tables vs tabs for document layout. When should each be used for optimal formatting and accessibility?', '[]'::jsonb, 'Tables: grid structure, data alignment, complex layouts. Tabs: simple alignment, lists, indentation. Accessibility: tables for data, not layout; tabs better for screen readers.', 9, 40, 'Design tables and templates', '["tables_vs_tabs","layout"]'::jsonb, 'analyze', '["word","layout"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 63, 'essay', 'hard', 'Analyze how document automation features (fields, macros, templates) improve efficiency in business document production and reduce errors.', '[]'::jsonb, 'Fields: dynamic content (dates, page numbers). Macros: automate repetitive tasks. Templates: ensure consistency. Benefits: time savings, reduced errors, brand consistency, faster onboarding.', 10, 45, 'Design tables and templates', '["document_automation","efficiency"]'::jsonb, 'evaluate', '["word","automation"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 64, 'practical', 'medium', 'Create a mail merge for personalized invitation letters using a data source with names, addresses, and event details.', '[]'::jsonb, 'Main document: invitation template with merge fields. Data source: spreadsheet with recipient data. Output: merged letters with personalized information.', 6, 30, 'Create mail merge documents', '["mail_merge_practical"]'::jsonb, 'create', '["word","mail_merge"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 65, 'practical', 'hard', 'Design a company report template with cover page, table of contents, section headers, page numbering, and consistent styling throughout.', '[]'::jsonb, 'Template includes: cover page design, TOC field, heading styles (Heading 1, 2, 3), header/footer with logo and page numbers, consistent fonts/colors.', 7, 35, 'Design tables and templates', '["report_template_design"]'::jsonb, 'create', '["word","template"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 61, 'practical', 'medium', 'Create a table to compare product features with proper formatting, merged cells, and calculations if needed.', '[]'::jsonb, 'Table: products as rows, features as columns. Formatting: borders, shading, alignment. Calculations: totals or ratings if applicable. Professional appearance.', 5, 25, 'Design tables and templates', '["table_creation_formatting"]'::jsonb, 'create', '["word","tables"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 62, 'case_study', 'hard', 'Case: A university department needs to produce hundreds of personalized certificates. Design a mail merge solution with templates, data management, and quality control.', '[]'::jsonb, 'Solution: certificate template with merge fields, student database as source, batch printing process, verification steps to ensure accuracy, archival system.', 15, 60, 'Create mail merge documents', '["certificate_production","mail_merge"]'::jsonb, 'create', '["word","case_study"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 63, 'case_study', 'medium', 'Case: Compare creating a company handbook as a single long document vs multiple linked documents. Analyze editing, distribution, and update challenges.', '[]'::jsonb, 'Single document: easier printing, complete TOC, but large file size. Multiple documents: easier to update sections, collaborative editing, but navigation challenges. Hybrid approach recommended.', 12, 45, 'Manage long documents with TOC and references', '["handbook_structure","comparison"]'::jsonb, 'evaluate', '["word","structure"]'::jsonb, 0, TRUE, 21, NULL),
(4, 33, 64, 'case_study', 'hard', 'Case: Analyze how legal documents use advanced word processing features: numbered paragraphs, cross-references, revision tracking, and digital signatures.', '[]'::jsonb, 'Features: automatic paragraph numbering, cross-references to clauses, track changes for negotiations, digital signatures for authentication. Importance for accuracy and legal validity.', 15, 55, 'Design tables and templates', '["legal_documents","advanced_features"]'::jsonb, 'evaluate', '["word","legal"]'::jsonb, 0, TRUE, 21, NULL),

-- Study Unit 4 (id=34): Spreadsheet Basics
(4, 34, 65, 'multiple_choice', 'easy', 'What is the intersection of a row and column called in a spreadsheet?', '["Cell","Box","Field","Square"]'::jsonb, 'Cell', 1, 10, 'Create and format spreadsheets', '["cell_definition"]'::jsonb, 'remember', '["spreadsheet","basics"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 61, 'multiple_choice', 'medium', 'Which symbol must all formulas begin with?', '["=","+","#","$"]'::jsonb, '=', 1, 10, 'Use basic formulas and functions', '["formula_syntax"]'::jsonb, 'remember', '["spreadsheet","formulas"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 62, 'multiple_choice', 'easy', 'What does the SUM function do?', '["Finds average","Adds numbers","Counts cells","Multiplies numbers"]'::jsonb, 'Adds numbers', 1, 10, 'Use basic formulas and functions', '["SUM_function"]'::jsonb, 'remember', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 63, 'true_false', 'medium', 'Cell references automatically adjust when you copy formulas.', '["True","False"]'::jsonb, 'True', 1, 5, 'Apply cell referencing', '["relative_references"]'::jsonb, 'understand', '["spreadsheet","references"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 64, 'true_false', 'easy', 'Spreadsheets can only contain numbers, not text.', '["True","False"]'::jsonb, 'False', 1, 5, 'Create and format spreadsheets', '["spreadsheet_content_types"]'::jsonb, 'remember', '["spreadsheet","basics"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 65, 'true_false', 'medium', 'The AVERAGE function ignores empty cells in its calculation.', '["True","False"]'::jsonb, 'True', 1, 5, 'Use basic formulas and functions', '["AVERAGE_function_behavior"]'::jsonb, 'understand', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 61, 'short_answer', 'easy', 'Name three basic spreadsheet functions.', '[]'::jsonb, 'SUM, AVERAGE, COUNT, MIN, MAX (any three)', 2, 10, 'Use basic formulas and functions', '["basic_functions_list"]'::jsonb, 'remember', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 62, 'short_answer', 'medium', 'What is the difference between relative and absolute cell references?', '[]'::jsonb, 'Relative: changes when copied (A1). Absolute: stays fixed when copied ($A$1). Mixed: one part fixed ($A1 or A$1).', 3, 15, 'Apply cell referencing', '["reference_types_difference"]'::jsonb, 'understand', '["spreadsheet","references"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 63, 'short_answer', 'hard', 'Explain how to use the SUM function to add values from non-adjacent cells.', '[]'::jsonb, 'Use: =SUM(cell1, cell2, cell3) or =SUM(range1, range2) where ranges/cells are separated by commas.', 3, 20, 'Use basic formulas and functions', '["SUM_non_adjacent"]'::jsonb, 'apply', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 64, 'essay', 'hard', 'Discuss best practices for spreadsheet design: structure, naming conventions, documentation, and error checking for maintainable and accurate spreadsheets.', '[]'::jsonb, 'Structure: logical layout, separate data/calculations/output. Naming: clear headers, named ranges. Documentation: comments, instructions sheet. Error checking: formulas audit, validation, testing.', 10, 45, 'Create and format spreadsheets', '["spreadsheet_design_best_practices"]'::jsonb, 'analyze', '["spreadsheet","design"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 65, 'essay', 'medium', 'Compare using spreadsheets vs word processors for creating tables of data. When is each more appropriate?', '[]'::jsonb, 'Spreadsheets: calculations, sorting, filtering, data analysis, large datasets. Word processors: presentation-ready tables, narrative integration, simple layouts. Choose based on need for calculations vs formatting.', 9, 40, 'Create and format spreadsheets', '["spreadsheet_vs_word_tables"]'::jsonb, 'analyze', '["spreadsheet","comparison"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 61, 'essay', 'hard', 'Analyze common spreadsheet errors (circular references, divide by zero, incorrect ranges) and strategies to prevent and detect them.', '[]'::jsonb, 'Errors: circular references (self-reference), #DIV/0! (divide by zero), #VALUE! (wrong data type). Prevention: data validation, formula auditing, error checking functions (IFERROR), testing.', 10, 45, 'Use basic formulas and functions', '["spreadsheet_errors_prevention"]'::jsonb, 'evaluate', '["spreadsheet","errors"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 62, 'practical', 'medium', 'Create a simple budget spreadsheet with income, expenses, and savings calculation using basic formulas.', '[]'::jsonb, 'Spreadsheet: income section, expense categories, formulas for totals, net income calculation, savings percentage. Formatting for readability.', 6, 30, 'Use basic formulas and functions', '["budget_spreadsheet_creation"]'::jsonb, 'create', '["spreadsheet","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 63, 'practical', 'hard', 'Build a gradebook with student names, assignment scores, total calculation, average, and letter grade conversion using nested IF statements.', '[]'::jsonb, 'Gradebook: student data, assignment columns, weighted total, average, letter grade (A-F) using IF or VLOOKUP. Formulas for automatic calculation.', 7, 35, 'Apply cell referencing', '["gradebook_spreadsheet"]'::jsonb, 'create', '["spreadsheet","gradebook"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 64, 'practical', 'medium', 'Format a sales data table with currency formatting, borders, conditional formatting for high/low values, and freeze panes for navigation.', '[]'::jsonb, 'Table: product sales data. Formatting: currency for prices, borders for readability, conditional formatting to highlight top/bottom values, freeze header row.', 5, 25, 'Create and format spreadsheets', '["table_formatting_practical"]'::jsonb, 'apply', '["spreadsheet","formatting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 65, 'case_study', 'hard', 'Case: A small business tracks inventory manually. Design a spreadsheet system for inventory management with reorder alerts and value calculations.', '[]'::jsonb, 'System: product database, current stock, reorder levels, supplier info. Formulas: stock value, reorder flags, lead time calculations. Dashboard for quick overview.', 15, 60, 'Use basic formulas and functions', '["inventory_management_spreadsheet"]'::jsonb, 'create', '["spreadsheet","inventory"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 61, 'case_study', 'medium', 'Case: Compare spreadsheet-based expense tracking vs dedicated accounting software for a freelancer. Analyze complexity, reporting, and scalability.', '[]'::jsonb, 'Spreadsheet: flexible, low cost, manual entry, error-prone. Accounting software: automated, reports, tax ready, cost. Recommendation based on business size and complexity.', 12, 45, 'Create and format spreadsheets', '["expense_tracking_comparison"]'::jsonb, 'evaluate', '["spreadsheet","accounting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 34, 62, 'case_study', 'hard', 'Case: Analyze the risks of spreadsheet errors in financial decision-making and propose quality control processes for business-critical spreadsheets.', '[]'::jsonb, 'Risks: incorrect formulas lead to wrong decisions, financial loss, compliance issues. Controls: version control, peer review, testing, documentation, audit trails, limit complexity.', 15, 55, 'Use basic formulas and functions', '["spreadsheet_risk_management"]'::jsonb, 'evaluate', '["spreadsheet","risk"]'::jsonb, 0, TRUE, 21, NULL);


INSERT INTO questions (course_id, study_unit_id, created_by, question_type, difficulty_level, question_text, options, correct_answer, marks, time_allocation, learning_outcome, keywords, bloom_taxonomy, tags, usage_count, is_active, approved_by, approved_at) VALUES
-- Study Unit 5 (id=35): Advanced Spreadsheet Functions
(4, 35, 63, 'multiple_choice', 'easy', 'Which function looks up values in a table?', '["SUMIF","VLOOKUP","COUNTIF","IF"]'::jsonb, 'VLOOKUP', 1, 10, 'Use advanced functions (VLOOKUP, IF, etc.)', '["VLOOKUP_function"]'::jsonb, 'remember', '["spreadsheet","advanced"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 64, 'multiple_choice', 'medium', 'What does the IF function do?', '["Performs logical test","Adds numbers","Counts cells","Looks up values"]'::jsonb, 'Performs logical test', 1, 10, 'Use advanced functions (VLOOKUP, IF, etc.)', '["IF_function_purpose"]'::jsonb, 'remember', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 65, 'multiple_choice', 'easy', 'What is a pivot table used for?', '["Data summarization","Chart creation","Cell formatting","Formula checking"]'::jsonb, 'Data summarization', 1, 10, 'Create pivot tables', '["pivot_table_purpose"]'::jsonb, 'remember', '["spreadsheet","pivot"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 61, 'true_false', 'medium', 'VLOOKUP can search for values to the left of the lookup column.', '["True","False"]'::jsonb, 'False', 1, 5, 'Use advanced functions (VLOOKUP, IF, etc.)', '["VLOOKUP_limitations"]'::jsonb, 'understand', '["spreadsheet","VLOOKUP"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 62, 'true_false', 'easy', 'COUNTIF counts cells based on a condition.', '["True","False"]'::jsonb, 'True', 1, 5, 'Use advanced functions (VLOOKUP, IF, etc.)', '["COUNTIF_function"]'::jsonb, 'remember', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 63, 'true_false', 'medium', 'Pivot tables modify the original data source.', '["True","False"]'::jsonb, 'False', 1, 5, 'Create pivot tables', '["pivot_table_nondestructive"]'::jsonb, 'understand', '["spreadsheet","pivot"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 64, 'short_answer', 'easy', 'Name three logical functions in spreadsheets.', '[]'::jsonb, 'IF, AND, OR, NOT, XOR (any three)', 2, 10, 'Use advanced functions (VLOOKUP, IF, etc.)', '["logical_functions_list"]'::jsonb, 'remember', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 65, 'short_answer', 'medium', 'What is the difference between VLOOKUP and HLOOKUP?', '[]'::jsonb, 'VLOOKUP searches vertically in columns, HLOOKUP searches horizontally in rows. Both return corresponding values from tables.', 3, 15, 'Use advanced functions (VLOOKUP, IF, etc.)', '["VLOOKUP_vs_HLOOKUP"]'::jsonb, 'understand', '["spreadsheet","lookup"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 61, 'short_answer', 'hard', 'Explain how nested IF functions work and when they might be replaced with IFS or SWITCH functions.', '[]'::jsonb, 'Nested IF: IF inside IF for multiple conditions. Limitations: complex, hard to read. IFS: multiple conditions sequentially. SWITCH: match specific values. Modern alternatives improve readability.', 3, 20, 'Use advanced functions (VLOOKUP, IF, etc.)', '["nested_IF_alternatives"]'::jsonb, 'analyze', '["spreadsheet","functions"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 62, 'essay', 'hard', 'Discuss data analysis capabilities of spreadsheets: pivot tables, data validation, conditional formatting, and what-if analysis tools.', '[]'::jsonb, 'Pivot tables: multidimensional analysis. Data validation: ensure data quality. Conditional formatting: visual patterns. What-if: scenario analysis, goal seek. Enables business intelligence without specialized software.', 10, 45, 'Perform data analysis', '["spreadsheet_analysis_capabilities"]'::jsonb, 'analyze', '["spreadsheet","analysis"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 63, 'essay', 'medium', 'Compare VLOOKUP, INDEX-MATCH, and XLOOKUP functions for data retrieval. Discuss advantages, limitations, and when to use each.', '[]'::jsonb, 'VLOOKUP: simple, left-to-right only. INDEX-MATCH: flexible, any direction, complex. XLOOKUP: modern, default values, bidirectional. Recommendation based on version and needs.', 9, 40, 'Use advanced functions (VLOOKUP, IF, etc.)', '["lookup_functions_comparison"]'::jsonb, 'analyze', '["spreadsheet","lookup"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 64, 'essay', 'hard', 'Analyze how spreadsheet modeling supports business decision-making: forecasting, sensitivity analysis, and scenario planning with practical examples.', '[]'::jsonb, 'Modeling: financial projections, budget scenarios. Sensitivity: change variables to see impacts. Scenario: best/worst case planning. Examples: sales forecasts, investment analysis, project planning.', 10, 45, 'Perform data analysis', '["spreadsheet_modeling","decision_support"]'::jsonb, 'evaluate', '["spreadsheet","modeling"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 65, 'practical', 'medium', 'Create a sales commission calculator using IF functions for tiered commission rates based on sales amounts.', '[]'::jsonb, 'Calculator: sales input, tiered rates (e.g., 5% up to $10k, 7% $10k-20k, 10% above), commission calculation using nested IF or IFS.', 6, 30, 'Use advanced functions (VLOOKUP, IF, etc.)', '["commission_calculator"]'::jsonb, 'create', '["spreadsheet","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 61, 'practical', 'hard', 'Build a pivot table from sales data to analyze revenue by product category, region, and time period with slicers for interactive filtering.', '[]'::jsonb, 'Pivot table: rows (category), columns (region), values (sum of revenue). Slicers: time period, salesperson. Interactive analysis dashboard.', 7, 35, 'Create pivot tables', '["pivot_table_analysis"]'::jsonb, 'create', '["spreadsheet","pivot"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 62, 'practical', 'medium', 'Use data validation to create a drop-down list for expense categories and conditional formatting to highlight expenses above budget.', '[]'::jsonb, 'Data validation: list of categories (Travel, Supplies, etc.). Conditional formatting: highlight cells where actual > budget with red fill.', 5, 25, 'Perform data analysis', '["data_validation_conditional_formatting"]'::jsonb, 'apply', '["spreadsheet","validation"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 63, 'case_study', 'hard', 'Case: A retail chain needs sales analysis across multiple stores. Design a consolidated reporting system using pivot tables and lookup functions from multiple data sources.', '[]'::jsonb, 'System: data consolidation from store files, pivot tables for multi-dimensional analysis (store, product, time), lookup for pricing/employee data, dashboard for management.', 15, 60, 'Create pivot tables', '["multi_store_analysis_system"]'::jsonb, 'create', '["spreadsheet","retail"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 64, 'case_study', 'medium', 'Case: Compare using spreadsheets vs database for customer relationship management. Analyze data volume, reporting, and multi-user access requirements.', '[]'::jsonb, 'Spreadsheets: small data, flexible, single-user. Database: large data, structured queries, multi-user, security. Hybrid: spreadsheet front-end to database for reporting.', 12, 45, 'Perform data analysis', '["spreadsheet_vs_database_CRM"]'::jsonb, 'evaluate', '["spreadsheet","database"]'::jsonb, 0, TRUE, 21, NULL),
(4, 35, 65, 'case_study', 'hard', 'Case: Analyze financial modeling for a startup business plan: revenue projections, expense forecasting, cash flow analysis, and break-even calculation using spreadsheet tools.', '[]'::jsonb, 'Model: revenue drivers, fixed/variable costs, cash flow projections, break-even analysis. Tools: formulas, data tables, scenario manager, charts for presentation.', 15, 55, 'Perform data analysis', '["financial_modeling_startup"]'::jsonb, 'evaluate', '["spreadsheet","financial"]'::jsonb, 0, TRUE, 21, NULL);


INSERT INTO questions (course_id, study_unit_id, created_by, question_type, difficulty_level, question_text, options, correct_answer, marks, time_allocation, learning_outcome, keywords, bloom_taxonomy, tags, usage_count, is_active, approved_by, approved_at) VALUES
-- Study Unit 6 (id=36): Charts and Visualization
(4, 36, 61, 'multiple_choice', 'easy', 'Which chart type is best for showing trends over time?', '["Pie chart","Bar chart","Line chart","Scatter plot"]'::jsonb, 'Line chart', 1, 10, 'Select appropriate visualizations', '["chart_selection","trends"]'::jsonb, 'remember', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 62, 'multiple_choice', 'medium', 'What does a pie chart represent?', '["Relationships between variables","Parts of a whole","Changes over time","Comparisons between items"]'::jsonb, 'Parts of a whole', 1, 10, 'Select appropriate visualizations', '["pie_chart_purpose"]'::jsonb, 'remember', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 63, 'multiple_choice', 'easy', 'Which chart element explains what colors/symbols represent?', '["Title","Axis","Legend","Gridlines"]'::jsonb, 'Legend', 1, 10, 'Customize chart elements', '["chart_legend"]'::jsonb, 'remember', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 64, 'true_false', 'medium', 'Bar charts are only for vertical bars; column charts are for horizontal bars.', '["True","False"]'::jsonb, 'False', 1, 5, 'Select appropriate visualizations', '["bar_vs_column_charts"]'::jsonb, 'understand', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 65, 'true_false', 'easy', 'Charts automatically update when source data changes.', '["True","False"]'::jsonb, 'True', 1, 5, 'Create various chart types', '["chart_data_linking"]'::jsonb, 'remember', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 61, 'true_false', 'medium', '3D effects always improve chart readability.', '["True","False"]'::jsonb, 'False', 1, 5, 'Customize chart elements', '["3D_charts_limitations"]'::jsonb, 'understand', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 62, 'short_answer', 'easy', 'Name three common chart types.', '[]'::jsonb, 'Column, Bar, Line, Pie, Scatter, Area (any three)', 2, 10, 'Create various chart types', '["chart_types_list"]'::jsonb, 'remember', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 63, 'short_answer', 'medium', 'What is the difference between a chart title and axis titles?', '[]'::jsonb, 'Chart title: overall chart description. Axis titles: labels for X and Y axes explaining what each axis represents.', 3, 15, 'Customize chart elements', '["chart_titles_explanation"]'::jsonb, 'understand', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 64, 'short_answer', 'hard', 'Explain when to use a scatter plot versus a line chart for data visualization.', '[]'::jsonb, 'Scatter plot: show relationship between two variables, correlation. Line chart: show trend over time, continuous data. Different purposes: correlation vs trend analysis.', 3, 20, 'Select appropriate visualizations', '["scatter_vs_line_usage"]'::jsonb, 'analyze', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 65, 'essay', 'hard', 'Discuss principles of effective data visualization: choosing appropriate chart types, simplifying design, emphasizing key insights, and avoiding misleading representations.', '[]'::jsonb, 'Principles: match chart to data type, minimize chart junk, use color strategically, highlight important data, provide context, maintain accuracy (avoid truncated axes, distorted scales).', 10, 45, 'Select appropriate visualizations', '["data_viz_principles"]'::jsonb, 'analyze', '["spreadsheet","visualization"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 61, 'essay', 'medium', 'Compare dashboard creation using multiple charts vs single complex visualizations. Discuss readability, information density, and audience considerations.', '[]'::jsonb, 'Multiple charts: separate views, compare metrics, clear but space-consuming. Single complex viz: comprehensive view, relationships, but potentially confusing. Dashboard design principles: balance, hierarchy, interactivity.', 9, 40, 'Customize chart elements', '["dashboard_design_principles"]'::jsonb, 'analyze', '["spreadsheet","dashboard"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 62, 'essay', 'hard', 'Analyze how interactive visualization features (slicers, timelines, drill-down) enhance data exploration and decision-making in business contexts.', '[]'::jsonb, 'Interactive features: slicers (filter across charts), timelines (time-based filtering), drill-down (detail on demand). Benefits: user exploration, personalized views, faster insights, reduced static reporting.', 10, 45, 'Select appropriate visualizations', '["interactive_visualization_benefits"]'::jsonb, 'evaluate', '["spreadsheet","interactive"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 63, 'practical', 'medium', 'Create a combination chart showing both sales amounts (columns) and growth percentage (line) on secondary axis.', '[]'::jsonb, 'Chart: primary axis (sales columns), secondary axis (growth line). Proper labeling, dual axis titles, legend, appropriate scaling.', 6, 30, 'Create various chart types', '["combination_chart_creation"]'::jsonb, 'create', '["spreadsheet","charts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 64, 'practical', 'hard', 'Design a sales dashboard with multiple linked charts (regional sales, product performance, monthly trends) and slicers for filtering.', '[]'::jsonb, 'Dashboard: 3-4 charts showing different perspectives. Slicers: region, product category, time period. Layout: logical arrangement, consistent styling, clear titles.', 7, 35, 'Customize chart elements', '["dashboard_design_practical"]'::jsonb, 'create', '["spreadsheet","dashboard"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 65, 'practical', 'medium', 'Improve a poorly designed chart by applying best practices: simplify, add titles, adjust colors, remove clutter, and highlight key data points.', '[]'::jsonb, 'Before/after analysis: identify problems (clutter, misleading scales, poor colors), implement improvements (clean design, clear labels, strategic emphasis).', 5, 25, 'Select appropriate visualizations', '["chart_redesign_practical"]'::jsonb, 'apply', '["spreadsheet","design"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 61, 'case_study', 'hard', 'Case: A marketing team needs to visualize campaign performance across channels. Design a visualization strategy with appropriate chart types for different metrics (ROI, engagement, conversion).', '[]'::jsonb, 'Strategy: ROI → bar charts (comparison), engagement over time → line charts, conversion funnel → waterfall/bar, demographic breakdown → pie/donut. Dashboard layout and update process.', 15, 60, 'Select appropriate visualizations', '["marketing_visualization_strategy"]'::jsonb, 'create', '["spreadsheet","marketing"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 62, 'case_study', 'medium', 'Case: Compare static reports vs interactive dashboards for executive reporting. Analyze development effort, user engagement, and maintenance requirements.', '[]'::jsonb, 'Static reports: easy to create, PDF/print, no interaction. Dashboards: development effort, real-time, interactive, higher engagement. Choice depends on audience needs and data frequency.', 12, 45, 'Customize chart elements', '["reports_vs_dashboards_comparison"]'::jsonb, 'evaluate', '["spreadsheet","reporting"]'::jsonb, 0, TRUE, 21, NULL),
(4, 36, 63, 'case_study', 'hard', 'Case: Analyze accessibility considerations in data visualization: color blindness, screen reader compatibility, and alternative text for charts in business reporting.', '[]'::jsonb, 'Considerations: color palette for color blindness (avoid red-green), data table equivalents for screen readers, alt text descriptions, sufficient contrast, simple designs for clarity.', 15, 55, 'Select appropriate visualizations', '["accessible_visualization_design"]'::jsonb, 'evaluate', '["spreadsheet","accessibility"]'::jsonb, 0, TRUE, 21, NULL);


