(4, 37, 62, 'true_false', 'medium', 'Presentation templates include both design and sample content.', '["True","False"]'::jsonb, 'True', 1, 5, 'Apply design themes', '["templates_content_design"]'::jsonb, 'understand', '["presentation","templates"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 63, 'true_false', 'easy', 'You can insert images into presentation slides.', '["True","False"]'::jsonb, 'True', 1, 5, 'Insert and format media', '["media_insertion"]'::jsonb, 'remember', '["presentation","media"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 64, 'true_false', 'medium', 'The same font size should be used for all text on every slide.', '["True","False"]'::jsonb, 'False', 1, 5, 'Apply design themes', '["font_size_variation"]'::jsonb, 'understand', '["presentation","design"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 65, 'short_answer', 'easy', 'Name three elements that can be added to a presentation slide.', '[]'::jsonb, 'Text, Images, Shapes, Charts, Tables, Videos (any three)', 2, 10, 'Insert and format media', '["slide_elements_list"]'::jsonb, 'remember', '["presentation","elements"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 61, 'short_answer', 'medium', 'What is the purpose of slide master in presentation software?', '[]'::jsonb, 'Slide master: controls overall design (fonts, colors, layouts) for all slides, ensures consistency, allows global changes.', 3, 15, 'Apply design themes', '["slide_master_purpose"]'::jsonb, 'understand', '["presentation","master"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 62, 'short_answer', 'hard', 'Explain the 6x6 rule for presentation slides and why it improves effectiveness.', '[]'::jsonb, '6x6 rule: maximum 6 words per line, 6 lines per slide. Improves: readability, focus on speaker, prevents text overload, maintains audience attention.', 3, 20, 'Create presentation slides', '["6x6_rule_presentation"]'::jsonb, 'analyze', '["presentation","design"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 63, 'essay', 'hard', 'Discuss effective presentation structure: opening, body, and closing. Include slide count recommendations and content distribution for different presentation lengths.', '[]'::jsonb, 'Structure: opening (title, agenda, hook), body (main points with evidence), closing (summary, Q&A, call to action). Slide count: 10-15 for 20 min, 20-30 for 45 min. Rule: 1-2 minutes per slide.', 10, 45, 'Create presentation slides', '["presentation_structure_guidelines"]'::jsonb, 'analyze', '["presentation","structure"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 64, 'essay', 'medium', 'Compare different presentation software (PowerPoint, Google Slides, Keynote, Prezi) in terms of features, collaboration, and platform compatibility.', '[]'::jsonb, 'PowerPoint: industry standard, feature-rich. Google Slides: cloud collaboration, simple. Keynote: macOS elegant design. Prezi: non-linear zooming. Choice depends on needs and ecosystem.', 9, 40, 'Navigate software interfaces', '["presentation_software_comparison"]'::jsonb, 'analyze', '["presentation","software"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 65, 'essay', 'hard', 'Analyze how visual design principles (contrast, alignment, repetition, proximity) apply to effective presentation slide creation.', '[]'::jsonb, 'Contrast: highlight important elements. Alignment: create order. Repetition: consistent styling. Proximity: group related items. Creates professional, readable slides that guide audience attention.', 10, 45, 'Apply design themes', '["visual_design_principles_presentations"]'::jsonb, 'evaluate', '["presentation","design"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 61, 'practical', 'medium', 'Create a 5-slide presentation introducing yourself with title slide, background, skills, goals, and thank you slide.', '[]'::jsonb, 'Slides: 1) Title/name, 2) Background/education, 3) Skills/experience, 4) Career goals, 5) Thank you/contact. Consistent design, appropriate visuals, concise text.', 6, 30, 'Create presentation slides', '["self_introduction_presentation"]'::jsonb, 'create', '["presentation","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 62, 'practical', 'hard', 'Design a company profile presentation template using slide master with logo placement, color scheme, font styles, and layout variations.', '[]'::jsonb, 'Template: slide master with logo, footer, color theme. Layouts: title, section header, content (2-column, bullet), quote, team, chart. Consistent professional design.', 7, 35, 'Apply design themes', '["presentation_template_design"]'::jsonb, 'create', '["presentation","template"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 63, 'practical', 'medium', 'Convert a dense text document into presentation slides by extracting key points and creating visual representations.', '[]'::jsonb, 'Process: read document, identify key messages, create bullet points, add visuals (charts, icons), structure into logical slides. Before/after comparison.', 5, 25, 'Create presentation slides', '["document_to_presentation_conversion"]'::jsonb, 'apply', '["presentation","conversion"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 64, 'case_study', 'hard', 'Case: A sales team needs consistent presentation materials. Develop a branded presentation system with templates, image library, and usage guidelines.', '[]'::jsonb, 'System: company template (slide master), approved image bank, color/font guidelines, slide examples, do''s/don''ts, training materials, update process.', 15, 60, 'Apply design themes', '["branded_presentation_system"]'::jsonb, 'create', '["presentation","branding"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 65, 'case_study', 'medium', 'Case: Compare in-person presentations vs virtual presentations. Analyze design differences, engagement strategies, and technical requirements for each format.', '[]'::jsonb, 'In-person: larger fonts, fewer details, physical presence. Virtual: more detail (screen sharing), interactive elements, chat features, bandwidth considerations. Adaptation needed for virtual delivery.', 12, 45, 'Create presentation slides', '["presentation_format_comparison"]'::jsonb, 'evaluate', '["presentation","formats"]'::jsonb, 0, TRUE, 21, NULL),
(4, 37, 61, 'case_study', 'hard', 'Case: Analyze accessibility in presentations: readable fonts, color contrast, alt text for images, and providing materials in alternative formats for diverse audiences.', '[]'::jsonb, 'Accessibility: sans-serif fonts, high contrast, descriptive alt text, accessible PDF handouts, captioning for videos, consideration for color blindness, simple layouts.', 15, 55, 'Apply design themes', '["accessible_presentation_design"]'::jsonb, 'evaluate', '["presentation","accessibility"]'::jsonb, 0, TRUE, 21, NULL);


INSERT INTO questions (course_id, study_unit_id, created_by, question_type, difficulty_level, question_text, options, correct_answer, marks, time_allocation, learning_outcome, keywords, bloom_taxonomy, tags, usage_count, is_active, approved_by, approved_at) VALUES
-- Study Unit 8 (id=38): Advanced Presentation Techniques
(4, 38, 62, 'multiple_choice', 'easy', 'What do transitions control in presentations?', '["Movement between slides","Movement within slides","Sound effects","Printing options"]'::jsonb, 'Movement between slides', 1, 10, 'Apply animations and transitions', '["transitions_definition"]'::jsonb, 'remember', '["presentation","advanced"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 63, 'multiple_choice', 'medium', 'What is the presenter view?', '["Audience display","Speaker notes display","Print preview","Design view"]'::jsonb, 'Speaker notes display', 1, 10, 'Deliver effective presentations', '["presenter_view_purpose"]'::jsonb, 'remember', '["presentation","delivery"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 64, 'multiple_choice', 'easy', 'Which element should be used sparingly in professional presentations?', '["Clear text","Relevant images","Excessive animations","Data charts"]'::jsonb, 'Excessive animations', 1, 10, 'Apply animations and transitions', '["animation_restraint"]'::jsonb, 'remember', '["presentation","design"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 65, 'true_false', 'medium', 'Animations can help reveal information gradually during a presentation.', '["True","False"]'::jsonb, 'True', 1, 5, 'Apply animations and transitions', '["animation_purpose_gradual_reveal"]'::jsonb, 'understand', '["presentation","animations"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 61, 'true_false', 'easy', 'Video files can be embedded directly into presentations.', '["True","False"]'::jsonb, 'True', 1, 5, 'Integrate multimedia', '["video_embedding"]'::jsonb, 'remember', '["presentation","multimedia"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 62, 'true_false', 'medium', 'Hyperlinks in presentations can only link to websites, not other slides.', '["True","False"]'::jsonb, 'False', 1, 5, 'Apply animations and transitions', '["hyperlink_capabilities"]'::jsonb, 'understand', '["presentation","interactive"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 63, 'short_answer', 'easy', 'Name three types of animations in presentation software.', '[]'::jsonb, 'Entrance, Exit, Emphasis, Motion Paths (any three)', 2, 10, 'Apply animations and transitions', '["animation_types"]'::jsonb, 'remember', '["presentation","animations"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 64, 'short_answer', 'medium', 'What is the difference between animations and transitions?', '[]'::jsonb, 'Animations: movement within a slide (objects appear/move). Transitions: movement between slides (how one slide replaces another).', 3, 15, 'Apply animations and transitions', '["animations_vs_transitions"]'::jsonb, 'understand', '["presentation","advanced"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 65, 'short_answer', 'hard', 'Explain how to use the animation pane to control timing and sequence of animated elements.', '[]'::jsonb, 'Animation pane: shows all animations on slide, allows reordering, timing adjustment (start, duration, delay), effect options, trigger settings for precise control.', 3, 20, 'Apply animations and transitions', '["animation_pane_usage"]'::jsonb, 'analyze', '["presentation","animations"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 61, 'essay', 'hard', 'Discuss advanced presentation techniques: branching navigation, interactive elements, embedded video, and speaker support features for complex presentations.', '[]'::jsonb, 'Branching: non-linear navigation (hyperlinks). Interactive: quizzes, clickable maps. Video: demonstrations, testimonials. Speaker support: notes, timer, ink annotations. Use for training, sales demos, conferences.', 10, 45, 'Integrate multimedia', '["advanced_presentation_techniques"]'::jsonb, 'analyze', '["presentation","advanced"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 62, 'essay', 'medium', 'Compare different presentation delivery methods: live in-person, live virtual, recorded, and self-running kiosk mode. Discuss preparation differences for each.', '[]'::jsonb, 'In-person: rehearsal, physical presence. Virtual: tech check, engagement tools. Recorded: script, editing. Kiosk: automatic timing, loop. Different preparation, interaction, and technical requirements.', 9, 40, 'Deliver effective presentations', '["delivery_methods_comparison"]'::jsonb, 'analyze', '["presentation","delivery"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 63, 'essay', 'hard', 'Analyze how presentation software supports storytelling: visual narrative flow, emotional impact through multimedia, pacing with animations, and audience engagement strategies.', '[]'::jsonb, 'Storytelling: story arc structure, emotional images/videos, animation for pacing/reveals, audience participation (polls, questions). Creates memorable, persuasive presentations.', 10, 45, 'Deliver effective presentations', '["presentation_storytelling_techniques"]'::jsonb, 'evaluate', '["presentation","storytelling"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 64, 'practical', 'medium', 'Create an animated process flow diagram with sequential appearance of steps and connectors.', '[]'::jsonb, 'Diagram: shapes for steps, connectors between. Animations: each step appears in sequence (on click or timed), connectors appear after steps. Clear flow visualization.', 6, 30, 'Apply animations and transitions', '["animated_diagram_creation"]'::jsonb, 'create', '["presentation","animation"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 65, 'practical', 'hard', 'Record a narrated presentation with slide timings, embedded video, and export as a video file for sharing.', '[]'::jsonb, 'Process: write script, record narration (slide by slide), set slide timings, embed video clip, export as MP4/video format. Testing playback.', 7, 35, 'Integrate multimedia', '["narrated_presentation_recording"]'::jsonb, 'apply', '["presentation","recording"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 61, 'practical', 'medium', 'Design an interactive quiz within a presentation with question slides, answer feedback, and navigation back to main menu.', '[]'::jsonb, 'Quiz: title slide, question slides (multiple choice), feedback (correct/incorrect), navigation buttons (next, back, menu). Hyperlinks for navigation logic.', 5, 25, 'Apply animations and transitions', '["interactive_quiz_presentation"]'::jsonb, 'create', '["presentation","interactive"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 62, 'case_study', 'hard', 'Case: A training department needs interactive e-learning modules. Design a presentation-based training system with knowledge checks, branching scenarios, and completion tracking.', '[]'::jsonb, 'System: content slides, interactive quizzes, branching based on answers, progress tracking, completion certificate. Balance of content and engagement.', 15, 60, 'Integrate multimedia', '["e-learning_presentation_design"]'::jsonb, 'create', '["presentation","training"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 63, 'case_study', 'medium', 'Case: Compare Prezi''s zooming presentation style with traditional slide-based presentations. Analyze engagement, content organization, and learning curve.', '[]'::jsonb, 'Prezi: non-linear, spatial relationships, zoom effects, visually dynamic but can cause motion sickness. Traditional: linear, familiar, easier to create. Different cognitive approaches to information.', 12, 45, 'Deliver effective presentations', '["presentation_style_comparison"]'::jsonb, 'evaluate', '["presentation","styles"]'::jsonb, 0, TRUE, 21, NULL),
(4, 38, 64, 'case_study', 'hard', 'Case: Analyze technical presentation requirements for scientific conferences: complex data visualization, citation management, Q&A handling, and poster presentations as alternatives.', '[]'::jsonb, 'Scientific presentations: detailed data charts, citation of sources, handling technical questions, backup slides. Poster presentations: visual summary, one-on-one discussion. Different preparation and delivery.', 15, 55, 'Deliver effective presentations', '["scientific_presentation_requirements"]'::jsonb, 'evaluate', '["presentation","scientific"]'::jsonb, 0, TRUE, 21, NULL),

-- Study Unit 9 (id=39): Database Applications for End Users
(4, 39, 65, 'multiple_choice', 'easy', 'What is the main purpose of a database?', '["Create documents","Organize and store data","Make calculations","Design presentations"]'::jsonb, 'Organize and store data', 1, 10, 'Navigate database applications', '["database_purpose"]'::jsonb, 'remember', '["database","basics"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 61, 'multiple_choice', 'medium', 'What is a single piece of information in a database called?', '["Field","Record","Table","Report"]'::jsonb, 'Field', 1, 10, 'Enter and query data', '["database_field"]'::jsonb, 'remember', '["database","structure"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 62, 'multiple_choice', 'easy', 'Which database view shows data in rows and columns?', '["Design view","Datasheet view","Form view","Report view"]'::jsonb, 'Datasheet view', 1, 10, 'Navigate database applications', '["database_views"]'::jsonb, 'remember', '["database","interface"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 63, 'true_false', 'medium', 'A query is used to ask questions about data in a database.', '["True","False"]'::jsonb, 'True', 1, 5, 'Enter and query data', '["query_purpose"]'::jsonb, 'understand', '["database","queries"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 64, 'true_false', 'easy', 'Forms in databases are used for data entry.', '["True","False"]'::jsonb, 'True', 1, 5, 'Enter and query data', '["forms_purpose"]'::jsonb, 'remember', '["database","forms"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 65, 'true_false', 'medium', 'All databases require programming knowledge to use.', '["True","False"]'::jsonb, 'False', 1, 5, 'Navigate database applications', '["database_skills_misconception"]'::jsonb, 'understand', '["database","usability"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 61, 'short_answer', 'easy', 'Name three objects in a typical database application.', '[]'::jsonb, 'Tables, Queries, Forms, Reports, Macros (any three)', 2, 10, 'Navigate database applications', '["database_objects"]'::jsonb, 'remember', '["database","objects"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 62, 'short_answer', 'medium', 'What is the difference between a table and a form in database applications?', '[]'::jsonb, 'Table: stores data in rows/columns, datasheet view. Form: user interface for data entry/viewing, more user-friendly, controls data validation.', 3, 15, 'Enter and query data', '["table_vs_form_difference"]'::jsonb, 'understand', '["database","objects"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 63, 'short_answer', 'hard', 'Explain how filters and queries differ in database applications.', '[]'::jsonb, 'Filters: temporary view of data, simple criteria, applied to current view. Queries: saved, reusable, complex criteria, multiple tables, calculations, basis for forms/reports.', 3, 20, 'Enter and query data', '["filters_vs_queries"]'::jsonb, 'analyze', '["database","queries"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 64, 'essay', 'hard', 'Discuss how databases support business operations: customer relationship management, inventory tracking, order processing, and reporting. Provide examples.', '[]'::jsonb, 'CRM: customer data, interactions. Inventory: stock levels, reordering. Orders: processing, fulfillment. Reporting: sales analysis, performance metrics. Integrated database systems streamline operations.', 10, 45, 'Generate basic reports', '["database_business_applications"]'::jsonb, 'analyze', '["database","business"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 65, 'essay', 'medium', 'Compare using spreadsheets vs databases for data management. Discuss data volume, relationships, multi-user access, and reporting capabilities.', '[]'::jsonb, 'Spreadsheets: small data, flat structure, single-user focus, flexible analysis. Databases: large data, relationships, multi-user, robust queries, reporting. Transition when: data grows, relationships complex, multiple users need access.', 9, 40, 'Navigate database applications', '["spreadsheet_vs_database_comparison"]'::jsonb, 'analyze', '["database","comparison"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 61, 'essay', 'hard', 'Analyze data integrity in databases: validation rules, referential integrity, input masks, and how they prevent data errors compared to spreadsheets.', '[]'::jsonb, 'Validation: rules for data entry. Referential integrity: maintains relationships. Input masks: format control. Prevents: duplicates, orphan records, invalid formats. More robust than spreadsheet data validation.', 10, 45, 'Enter and query data', '["data_integrity_database"]'::jsonb, 'evaluate', '["database","integrity"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 62, 'practical', 'medium', 'Create a simple customer database with table for customer information and form for data entry.', '[]'::jsonb, 'Table: fields (CustomerID, Name, Email, Phone, Address). Form: user-friendly layout with labels, text boxes, navigation buttons. Data entry test.', 6, 30, 'Enter and query data', '["simple_database_creation"]'::jsonb, 'create', '["database","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 63, 'practical', 'hard', 'Design a query to find customers from a specific city who made purchases above a certain amount, sorted by purchase date.', '[]'::jsonb, 'Query: criteria: City = "Kampala" AND PurchaseAmount > 1000. Sorting: PurchaseDate DESC. Output: CustomerName, City, PurchaseAmount, PurchaseDate.', 7, 35, 'Enter and query data', '["database_query_design"]'::jsonb, 'create', '["database","queries"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 64, 'practical', 'medium', 'Create a report from sales data showing total sales by product category with grouping and summary calculations.', '[]'::jsonb, 'Report: data source (sales table), group by ProductCategory, summary fields (Sum of SalesAmount), formatting (headers, totals, currency). Professional layout.', 5, 25, 'Generate basic reports', '["database_report_creation"]'::jsonb, 'create', '["database","reports"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 65, 'case_study', 'hard', 'Case: A library needs to track books, members, and loans. Design a database system with tables, relationships, forms for check-in/out, and overdue reports.', '[]'::jsonb, 'System: Books table (ISBN, Title), Members table (MemberID, Name), Loans table (LoanID, BookID, MemberID, DueDate). Relationships, forms for transactions, overdue query/report.', 15, 60, 'Generate basic reports', '["library_database_design"]'::jsonb, 'create', '["database","library"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 61, 'case_study', 'medium', 'Case: Compare using a desktop database (Access) vs cloud database (Airtable, Google Sheets) for a small team project. Analyze setup, collaboration, and mobile access.', '[]'::jsonb, 'Desktop: powerful, offline, single-user focused. Cloud: real-time collaboration, mobile access, simpler setup. Choice depends on team size, technical skill, and access needs.', 12, 45, 'Navigate database applications', '["database_platform_comparison"]'::jsonb, 'evaluate', '["database","platforms"]'::jsonb, 0, TRUE, 21, NULL),
(4, 39, 62, 'case_study', 'hard', 'Case: Analyze data migration from spreadsheet to database: planning, cleaning, mapping fields, establishing relationships, and validation for a growing business.', '[]'::jsonb, 'Migration steps: 1) Assess spreadsheet data quality, 2) Design database structure, 3) Clean data (remove duplicates, standardize), 4) Map fields, 5) Import, 6) Validate, 7) Train users. Challenges: data quality, relationship definition.', 15, 55, 'Enter and query data', '["data_migration_planning"]'::jsonb, 'evaluate', '["database","migration"]'::jsonb, 0, TRUE, 21, NULL),

-- Study Unit 10 (id=40): Integrated Office Applications
(4, 40, 63, 'multiple_choice', 'easy', 'What does OLE stand for in office integration?', '["Object Linking and Embedding","Office Linkage Exchange","Online Linking Extension","Object Library Extension"]'::jsonb, 'Object Linking and Embedding', 1, 10, 'Link data between applications', '["OLE_definition"]'::jsonb, 'remember', '["integration","concepts"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 64, 'multiple_choice', 'medium', 'Which method maintains a connection to the source file?', '["Copy and Paste","Linking","Embedding","Screenshot"]'::jsonb, 'Linking', 1, 10, 'Link data between applications', '["linking_vs_embedding"]'::jsonb, 'remember', '["integration","techniques"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 65, 'multiple_choice', 'easy', 'What can be created by combining data from multiple office applications?', '["Integrated documents","Separate files","Only text documents","Only spreadsheets"]'::jsonb, 'Integrated documents', 1, 10, 'Create integrated documents', '["integrated_documents_purpose"]'::jsonb, 'remember', '["integration","purpose"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 61, 'true_false', 'medium', 'Embedded objects increase file size more than linked objects.', '["True","False"]'::jsonb, 'True', 1, 5, 'Link data between applications', '["embedding_file_size"]'::jsonb, 'understand', '["integration","techniques"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 62, 'true_false', 'easy', 'Charts from spreadsheets can be placed in presentation slides.', '["True","False"]'::jsonb, 'True', 1, 5, 'Create integrated documents', '["chart_integration"]'::jsonb, 'remember', '["integration","examples"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 63, 'true_false', 'medium', 'Collaborative features only work within the same application.', '["True","False"]'::jsonb, 'False', 1, 5, 'Apply collaborative features', '["cross_application_collaboration"]'::jsonb, 'understand', '["integration","collaboration"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 64, 'short_answer', 'easy', 'Name three ways to integrate data between office applications.', '[]'::jsonb, 'Copy/Paste, Linking, Embedding, Import/Export, Mail Merge (any three)', 2, 10, 'Link data between applications', '["integration_methods"]'::jsonb, 'remember', '["integration","methods"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 65, 'short_answer', 'medium', 'What is the difference between linking and embedding objects?', '[]'::jsonb, 'Linking: creates reference to source file, updates when source changes. Embedding: inserts copy into document, no connection to source, larger file size.', 3, 15, 'Link data between applications', '["linking_embedding_difference"]'::jsonb, 'understand', '["integration","techniques"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 61, 'short_answer', 'hard', 'Explain how mail merge integrates word processing with spreadsheet or database data.', '[]'::jsonb, 'Mail merge: uses data source (spreadsheet/database) to populate fields in word document, creating personalized documents (letters, labels) from template.', 3, 20, 'Create integrated documents', '["mail_merge_integration_explanation"]'::jsonb, 'analyze', '["integration","mail_merge"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 62, 'essay', 'hard', 'Discuss workflow automation using integrated office applications: data collection (forms), analysis (spreadsheets), reporting (word/presentation), and distribution.', '[]'::jsonb, 'Workflow: data entry via forms → spreadsheet analysis → automated reports in Word → presentation for meetings → email distribution. Integration reduces manual steps, ensures consistency.', 10, 45, 'Create integrated documents', '["workflow_automation_integration"]'::jsonb, 'analyze', '["integration","automation"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 63, 'essay', 'medium', 'Compare traditional file-based integration (OLE) with modern cloud-based integration (APIs, shared workspaces). Discuss advantages for collaboration and version control.', '[]'::jsonb, 'Traditional OLE: file links, version issues, single-user. Cloud integration: real-time collaboration, version history, accessibility, API connections. Modern approach supports distributed teams.', 9, 40, 'Apply collaborative features', '["integration_methods_comparison"]'::jsonb, 'analyze', '["integration","evolution"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 64, 'essay', 'hard', 'Analyze how integrated office suites support project management: documentation (Word), scheduling (spreadsheets), presentations (stakeholder updates), and task tracking (databases).', '[]'::jsonb, 'Project docs: Word templates. Scheduling: Gantt charts in spreadsheets. Updates: presentation decks. Task tracking: database or spreadsheet. Integration creates cohesive project management system.', 10, 45, 'Create integrated documents', '["project_management_integration"]'::jsonb, 'evaluate', '["integration","project"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 65, 'practical', 'medium', 'Create a business report with linked spreadsheet charts, embedded presentation slides, and database query results.', '[]'::jsonb, 'Report: Word document with linked Excel charts (updates when Excel changes), embedded PowerPoint slides for visuals, query results from database (formatted table).', 6, 30, 'Create integrated documents', '["integrated_business_report"]'::jsonb, 'create', '["integration","practical"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 61, 'practical', 'hard', 'Design an automated monthly sales report: Excel data analysis → Word report generation → PowerPoint summary → Outlook distribution.', '[]'::jsonb, 'Automation: Excel template for sales data, Word template with linked charts, PowerPoint slides from Word content, Outlook distribution list. Process documentation.', 7, 35, 'Link data between applications', '["automated_reporting_system"]'::jsonb, 'create', '["integration","automation"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 62, 'practical', 'medium', 'Collaborate on a document using cloud office suite features: real-time editing, comments, version history, and sharing controls.', '[]'::jsonb, 'Process: create document in cloud suite, share with team, demonstrate real-time co-editing, use comments for feedback, review version history, adjust sharing permissions.', 5, 25, 'Apply collaborative features', '["cloud_collaboration_practical"]'::jsonb, 'apply', '["integration","collaboration"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 63, 'case_study', 'hard', 'Case: A research team needs to collaborate on papers, data analysis, and presentations. Design an integrated workflow using office applications with version control and data consistency.', '[]'::jsonb, 'Workflow: shared data repository (database/spreadsheet), Word for paper writing with reference manager, Excel for analysis, PowerPoint for presentations. Cloud platform for collaboration, version naming conventions.', 15, 60, 'Apply collaborative features', '["research_collaboration_workflow"]'::jsonb, 'create', '["integration","research"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 64, 'case_study', 'medium', 'Case: Compare integrated office suites (Microsoft 365, Google Workspace) vs best-of-breed standalone applications. Analyze productivity, cost, and learning curve for a small business.', '[]'::jsonb, 'Integrated suite: consistent interface, data sharing, single vendor, subscription cost. Best-of-breed: specialized features, mix of vendors, potential integration challenges. Recommendation based on business needs and tech proficiency.', 12, 45, 'Link data between applications', '["suite_vs_standalone_comparison"]'::jsonb, 'evaluate', '["integration","selection"]'::jsonb, 0, TRUE, 21, NULL),
(4, 40, 65, 'case_study', 'hard', 'Case: Analyze digital transformation of office work: from paper-based processes to integrated digital workflows, including challenges of change management and training requirements.', '[]'::jsonb, 'Transformation: scanning documents → digital storage, manual forms → electronic forms, paper filing → database, meetings → video conferencing. Challenges: resistance to change, training needs, infrastructure, security concerns.', 15, 55, 'Apply collaborative features', '["digital_transformation_office"]'::jsonb, 'evaluate', '["integration","transformation"]'::jsonb, 0, TRUE, 21, NULL);


-- Study Unit 1: Number Systems and Arithmetic (18 questions) - COURSE 5
INSERT INTO questions (course_id, study_unit_id, created_by, question_type, difficulty_level, question_text, options, correct_answer, marks, time_allocation, learning_outcome, keywords, bloom_taxonomy, tags, usage_count, is_active, approved_by, approved_at) VALUES
-- 3 Multiple Choice
(5, 1, 66, 'multiple_choice', 'easy', 'Which number system uses base 2?', '["Decimal","Binary","Hexadecimal","Octal"]'::jsonb, 'Binary', 1, 10, 'Perform operations in various number systems', '["number_systems","binary"]'::jsonb, 'remember', '["math","number_systems"]'::jsonb, 0, TRUE, 22, NULL),
