-- 3 Short Answer
(5, 1, 67, 'short_answer', 'easy', 'Convert decimal 15 to binary.', '[]'::jsonb, '1111', 2, 10, 'Perform operations in various number systems', '["decimal_to_binary"]'::jsonb, 'apply', '["math","conversion"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 68, 'short_answer', 'medium', 'What is the hexadecimal equivalent of decimal 255?', '[]'::jsonb, 'FF', 3, 15, 'Perform operations in various number systems', '["decimal_to_hex"]'::jsonb, 'apply', '["math","conversion"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 69, 'short_answer', 'hard', 'Explain the associative property for addition and provide an example.', '[]'::jsonb, 'Associative property: (a + b) + c = a + (b + c). Example: (2 + 3) + 4 = 2 + (3 + 4) = 9.', 3, 20, 'Apply arithmetic properties', '["associative_property_explanation"]'::jsonb, 'analyze', '["math","properties"]'::jsonb, 0, TRUE, 22, NULL),

-- 3 Essay
(5, 1, 70, 'essay', 'hard', 'Discuss the importance of different number systems (binary, octal, hexadecimal) in computing and digital systems. Provide examples of where each is used.', '[]'::jsonb, 'Binary: fundamental to digital circuits, computer memory. Octal: historical use in systems, file permissions. Hexadecimal: memory addressing, color codes, assembly. Each offers efficient representation for different computing needs.', 10, 45, 'Solve computational problems', '["number_systems_computing_importance"]'::jsonb, 'analyze', '["math","computing"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 66, 'essay', 'medium', 'Compare and contrast positional number systems (decimal, binary, hexadecimal) with non-positional systems (Roman numerals). Discuss advantages for computation.', '[]'::jsonb, 'Positional: value depends on position, efficient for arithmetic, zero placeholder. Non-positional: symbols have fixed values, inefficient for calculations. Positional systems enable modern computing.', 9, 40, 'Perform operations in various number systems', '["positional_vs_nonpositional"]'::jsonb, 'analyze', '["math","number_systems"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 67, 'essay', 'hard', 'Analyze how arithmetic properties (commutative, associative, distributive) are exploited in computer algorithms and optimization techniques.', '[]'::jsonb, 'Commutative: parallel processing, reordering operations. Associative: regrouping for efficiency, tree reduction. Distributive: factorization, optimization in compilers. Fundamental to algorithm design and hardware implementation.', 10, 45, 'Apply arithmetic properties', '["arithmetic_properties_computing"]'::jsonb, 'evaluate', '["math","algorithms"]'::jsonb, 0, TRUE, 22, NULL),

-- 3 Practical
(5, 1, 68, 'practical', 'medium', 'Convert the following numbers: decimal 42 to binary, binary 11001 to decimal, hexadecimal 2A to decimal.', '[]'::jsonb, '42 = 101010, 11001 = 25, 2A = 42', 6, 30, 'Perform operations in various number systems', '["conversion_practice"]'::jsonb, 'apply', '["math","conversion"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 69, 'practical', 'hard', 'Perform binary arithmetic: 1011 + 1101, 1110 - 1011, 101 × 11. Show all steps.', '[]'::jsonb, '1011 + 1101 = 11000, 1110 - 1011 = 0011, 101 × 11 = 1111', 7, 35, 'Perform operations in various number systems', '["binary_arithmetic_practice"]'::jsonb, 'apply', '["math","binary"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 70, 'practical', 'medium', 'Use the distributive property to simplify and compute: 7 × (20 + 3). Compare with direct calculation.', '[]'::jsonb, '7 × 23 = 161. Using distributive: (7 × 20) + (7 × 3) = 140 + 21 = 161. Same result, demonstrates property.', 5, 25, 'Apply arithmetic properties', '["distributive_property_practical"]'::jsonb, 'apply', '["math","properties"]'::jsonb, 0, TRUE, 22, NULL),

-- 3 Case Study
(5, 1, 66, 'case_study', 'hard', 'Case: A computer system uses hexadecimal for memory addresses from 0000 to FFFF. Calculate total addressable memory locations and convert range to decimal.', '[]'::jsonb, 'Hex range: 0000 to FFFF = 0 to 65535 decimal. Total locations: 65536 (or 64KB). Explanation: FFFF = 16^4 - 1 = 65535, plus 0 = 65536 total.', 15, 60, 'Solve computational problems', '["memory_addressing_calculation"]'::jsonb, 'evaluate', '["math","computing"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 67, 'case_study', 'medium', 'Case: Design a number system conversion tool for a programming class. Specify input/output formats and algorithms for binary, decimal, hexadecimal conversions.', '[]'::jsonb, 'Tool design: input (number, base), output (all bases). Algorithms: division method for decimal to other bases, positional sum for other to decimal. User interface considerations.', 12, 45, 'Perform operations in various number systems', '["conversion_tool_design"]'::jsonb, 'create', '["math","tool"]'::jsonb, 0, TRUE, 22, NULL),
(5, 1, 68, 'case_study', 'hard', 'Case: Analyze error propagation in floating-point arithmetic due to finite representation in computers. Discuss implications for scientific computing and financial calculations.', '[]'::jsonb, 'Errors: rounding, cancellation, accumulation. Implications: scientific (accumulated errors affect results), financial (rounding errors in currency). Mitigation: careful algorithm design, error bounds, using decimal for finance.', 15, 55, 'Apply arithmetic properties', '["floating_point_errors"]'::jsonb, 'evaluate', '["math","computing"]'::jsonb, 0, TRUE, 22, NULL);


