(5, 2, 69, 'multiple_choice', 'easy', 'What is the solution to 2x + 5 = 15?', '["x = 5","x = 10","x = 7.5","x = 20"]'::jsonb, 'x = 5', 1, 10, 'Solve linear and quadratic equations', '["linear_equation_solution"]'::jsonb, 'apply', '["math","algebra"]'::jsonb, 0, TRUE, 22, NULL),
(5, 2, 70, 'multiple_choice', 'medium', 'Which is the factored form of x² - 4?', '["(x-2)(x+2)","(x-2)²","(x+2)²","(x-4)(x+1)"]'::jsonb, '(x-2)(x+2)', 1, 10, 'Simplify algebraic expressions', '["difference_of_squares"]'::jsonb, 'remember', '["math","algebra"]'::jsonb, 0, TRUE, 22, NULL),
